DROP TABLE IF EXISTS `gen_pipeline`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `gen_pipeline` (
  `id` bigint NOT NULL COMMENT '闆?姳ID',
  `pipeline_no` varchar(32) NOT NULL COMMENT '娴佹按绾垮彿 PPL+鏃堕棿鎴',
  `project_id` bigint DEFAULT NULL COMMENT '鍏宠仈 sys_project',
  `system_name` varchar(64) NOT NULL COMMENT '褰曞叆鐨勭郴缁熷悕绉',
  `system_desc` varchar(512) DEFAULT NULL COMMENT '涓?彞璇濅笟鍔℃弿杩',
  `db_name` varchar(64) NOT NULL COMMENT '鐩?爣鏁版嵁搴撳悕',
  `backend_port` int DEFAULT NULL,
  `frontend_port` int DEFAULT NULL,
  `mode` varchar(16) NOT NULL DEFAULT 'ai',
  `seed_mode` varchar(10) DEFAULT NULL COMMENT '数据初始化：rule规则生成/off跳过（NULL=off）',
  `status` varchar(16) NOT NULL DEFAULT 'draft',
  `current_step` varchar(32) DEFAULT NULL,
  `fail_reason` varchar(1024) DEFAULT NULL,
  `frontend_url` varchar(256) DEFAULT NULL,
  `backend_pid` bigint DEFAULT NULL,
  `frontend_pid` bigint DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_no` (`pipeline_no`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='V5.0 涓?彞璇濆缓绯荤粺娴佹按绾';
/*!40101 SET character_set_client = @saved_cs_client */;

