--
-- Table structure for table `gen_template`
--

DROP TABLE IF EXISTS `gen_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `gen_template` (
  `id` bigint NOT NULL COMMENT '主键',
  `tpl_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模板编码:entity/mapper/service/serviceImpl/pageDto/saveDto/vo/controller/apiJs/vuePage/routerSnippet/readme',
  `tpl_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '模板名称',
  `file_group` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产物分组:backend/frontend/shared',
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT 'Freemarker 模板内容',
  `path_pattern` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '输出相对路径模式（支持 ${var} 占位）',
  `table_id` bigint NOT NULL DEFAULT '0' COMMENT '归属表:0全局模板 >0表级覆盖',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态:0停用 1启用',
  `version` int NOT NULL DEFAULT '1' COMMENT '版本号，每次保存+1',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除:0否1是',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code_table` (`tpl_code`,`table_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='代码生成器-模板配置';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `gen_template`
--

LOCK TABLES `gen_template` WRITE;
/*!40000 ALTER TABLE `gen_template` DISABLE KEYS */;
INSERT INTO `gen_template` VALUES (2120016940794671105,'entity','实体类','backend','package ${pkg}.entity;\n\n<#if entityHasBigDecimal>import java.math.BigDecimal;\n</#if>\n<#if entityHasLocalDateTime>import java.time.LocalDateTime;\n</#if>\n<#if entityHasLocalDate>import java.time.LocalDate;\n</#if>\n<#if entityHasLocalTime>import java.time.LocalTime;\n</#if>\n<#if entityHasImport>${\'\'}\n</#if>\nimport com.baomidou.mybatisplus.annotation.TableName;\nimport ${rootPkg}.common.entity.BaseEntity;\nimport lombok.Data;\nimport lombok.EqualsAndHashCode;\n\n/**\n * ${comment}\n */\n@Data\n@EqualsAndHashCode(callSuper = true)\n@TableName(\"${tableName}\")\npublic class ${className} extends BaseEntity {\n\n    // <gen:begin key=\"entity-fields\">\n<#list columns as c>\n    /**\n     * ${c.columnComment}\n     */\n    private ${c.javaType} ${c.javaField};\n\n</#list>\n    // <gen:end key=\"entity-fields\">\n    // ===== 以下为手写区：写在 gen:end 之后的内容，重新生成不会被覆盖 =====\n}\n','${backendBase}/entity/${className}.java',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:21',NULL,'2026-11-10 12:53:21'),(2120016940912111617,'mapper','Mapper 接口','backend','package ${pkg}.mapper;\n\nimport com.baomidou.mybatisplus.core.mapper.BaseMapper;\nimport ${pkg}.entity.${className};\nimport org.apache.ibatis.annotations.Mapper;\n\n/**\n * ${comment} Mapper\n<#if hasDataScope> *\n * <p>数据权限：本表按 {@code ${scopeColumn}} 做 ${scopeType} 级隔离，\n * 登记在启动类 {@code common.datascope.DataScopeRegistry} 里，查询与更新都会自动追加条件。\n</#if>\n */\n@Mapper\npublic interface ${className}Mapper extends BaseMapper<${className}> {\n\n    // <gen:begin key=\"mapper-body\">\n    // <gen:end key=\"mapper-body\">\n    // ===== 以下为手写区：自定义方法写在这里，重新生成不会被覆盖 =====\n}\n','${backendBase}/mapper/${className}Mapper.java',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:21',NULL,'2026-11-10 12:53:21'),(2120016940975026177,'service','Service 接口','backend','package ${pkg}.service;\n\nimport com.baomidou.mybatisplus.extension.service.IService;\nimport ${pkg}.entity.${className};\n<#if genTree>import ${pkg}.vo.${className}VO;\nimport java.util.List;\n</#if>\n<#if hasChild>import ${pkg}.dto.${className}SaveDTO;\n<#list children as child>import ${pkg}.dto.${child.className}SaveDTO;\n</#list>import java.util.List;\n</#if>\n\n/**\n * ${comment} Service\n */\npublic interface ${className}Service extends IService<${className}> {\n\n    // <gen:begin key=\"service-body\">\n<#if genTree>\n    /**\n     * 树形列表（父子嵌套）\n     */\n    List<${className}VO> tree();\n</#if>\n<#if hasChild>\n    /**\n     * 主表 + 子表同事务保存（每张子表先清后插；参数为 null 表示该子表不动，空列表表示清空）\n     */\n    void saveWithChildren(${className}SaveDTO master<#list children as child>,\n                          List<${child.className}SaveDTO> ${child.varName}Rows</#list>);\n\n    /**\n     * V4.4 按表的删除级联模式删除主表：\n     * 级联=同事务删光全部子表（含三级）；阻止=还有子行就拒删；不处理=仅删主行。\n     */\n    void removeWithChildren(Long id);\n</#if>\n    // <gen:end key=\"service-body\">\n    // ===== 以下为手写区：自定义方法写在这里，重新生成不会被覆盖 =====\n}\n','${backendBase}/service/${className}Service.java',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:21',NULL,'2026-11-10 12:53:21'),(2120016941037940738,'serviceImplSimple','Service 实现（单表）','backend','package ${pkg}.service.impl;\n\nimport com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;\nimport ${pkg}.entity.${className};\nimport ${pkg}.mapper.${className}Mapper;\nimport ${pkg}.service.${className}Service;\nimport org.springframework.stereotype.Service;\n\n/**\n * ${comment} Service\n */\n@Service\npublic class ${className}ServiceImpl extends ServiceImpl<${className}Mapper, ${className}> implements ${className}Service {\n\n    // <gen:begin key=\"service-body\">\n    // <gen:end key=\"service-body\">\n    // ===== 以下为手写区：自定义方法写在这里，重新生成不会被覆盖 =====\n}\n','${backendBase}/service/impl/${className}ServiceImpl.java',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:21',NULL,'2026-11-10 12:53:21'),(2120016941155381250,'serviceImplTree','Service 实现（树形）','backend','package ${pkg}.service.impl;\n\n<#if genTree || hasChild>import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;\n</#if>import com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;\nimport ${pkg}.entity.${className};\nimport ${pkg}.mapper.${className}Mapper;\nimport ${pkg}.service.${className}Service;\n<#if genTree>import ${pkg}.vo.${className}VO;\nimport org.springframework.beans.BeanUtils;\n</#if>import org.springframework.stereotype.Service;\n<#if genTree>import java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.function.Function;\nimport java.util.stream.Collectors;\n</#if>\n\n/**\n * ${comment} Service\n */\n@Service\npublic class ${className}ServiceImpl extends ServiceImpl<${className}Mapper, ${className}> implements ${className}Service {\n\n    // <gen:begin key=\"service-body\">\n<#if genTree>\n    @Override\n    public List<${className}VO> tree() {\n        List<${className}> all = list(new LambdaQueryWrapper<${className}>().orderByAsc(${className}::getId));\n        List<${className}VO> vos = new ArrayList<>();\n        for (${className} entity : all) {\n            ${className}VO vo = new ${className}VO();\n            BeanUtils.copyProperties(entity, vo);\n            vos.add(vo);\n        }\n        Map<Long, ${className}VO> index = vos.stream()\n                .collect(Collectors.toMap(${className}VO::getId, Function.identity(), (a, b) -> a));\n        List<${className}VO> roots = new ArrayList<>();\n        for (${className}VO vo : vos) {\n            ${treeParentJavaType} parentId = vo.get${treeParentCapField}();\n            Long parentKey = parentId == null ? null : Long.valueOf(String.valueOf(parentId));\n            ${className}VO parent = parentKey == null ? null : index.get(parentKey);\n            if (parent == null || parent == vo) {\n                roots.add(vo);\n            } else {\n                parent.getChildren().add(vo);\n            }\n        }\n        return roots;\n    }\n</#if>\n    // <gen:end key=\"service-body\">\n    // ===== 以下为手写区：自定义方法写在这里，重新生成不会被覆盖 =====\n}\n','${backendBase}/service/impl/${className}ServiceImpl.java',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:21',NULL,'2026-11-10 12:53:21'),(2120016941218295810,'serviceImplMasterdetail','Service 实现（主子表）','backend','package ${pkg}.service.impl;\n\n<#if genTree || hasChild>import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;\n</#if>\nimport com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;\nimport ${pkg}.entity.${className};\nimport ${pkg}.mapper.${className}Mapper;\nimport ${pkg}.service.${className}Service;\n<#if genTree>import ${pkg}.vo.${className}VO;\n</#if>\nimport ${pkg}.dto.${className}SaveDTO;\n<#list children as child>\nimport ${pkg}.dto.${child.className}SaveDTO;\nimport ${pkg}.entity.${child.className};\nimport ${pkg}.mapper.${child.className}Mapper;\n<#-- 孙层的实体与 Mapper 同样要导入：save${gc.className}Rows 与级联删除都直接引用这两个类型。\n     漏了 import，生成的主子表实现类 javac 会直接「找不到符号」 -->\n<#list child.grandChildren as gc>\nimport ${gc.pkg}.entity.${gc.className};\nimport ${gc.pkg}.mapper.${gc.className}Mapper;\n</#list>\n</#list>\nimport org.springframework.beans.BeanUtils;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.transaction.annotation.Transactional;\nimport org.springframework.stereotype.Service;\n<#if deleteCascadeBlock>import ${rootPkg}.common.exception.BusinessException;\n</#if>\n<#if genTree>import java.util.ArrayList;\n</#if>\nimport java.util.List;\n<#if genTree>import java.util.Map;\nimport java.util.function.Function;\nimport java.util.stream.Collectors;\n</#if>\n\n/**\n * ${comment} Service\n */\n@Service\npublic class ${className}ServiceImpl extends ServiceImpl<${className}Mapper, ${className}> implements ${className}Service {\n\n    // <gen:begin key=\"service-body\">\n<#if hasChild>\n<#list children as child>\n    @Autowired\n    private ${child.className}Mapper ${child.varName}Mapper;\n<#-- 孙表 Mapper 必须跟着声明：saveXxxRows 的全量替换要用孙表 Mapper，漏了声明生成的代码编译不过 -->\n<#list child.grandChildren as gc>\n    @Autowired\n    private ${gc.className}Mapper ${gc.varName}Mapper;\n</#list>\n</#list>\n</#if>\n<#if genTree>\n    @Override\n    public List<${className}VO> tree() {\n        List<${className}> all = list(new LambdaQueryWrapper<${className}>().orderByAsc(${className}::getId));\n        List<${className}VO> vos = new ArrayList<>();\n        for (${className} entity : all) {\n            ${className}VO vo = new ${className}VO();\n            BeanUtils.copyProperties(entity, vo);\n            vos.add(vo);\n        }\n        Map<Long, ${className}VO> index = vos.stream()\n                .collect(Collectors.toMap(${className}VO::getId, Function.identity(), (a, b) -> a));\n        List<${className}VO> roots = new ArrayList<>();\n        for (${className}VO vo : vos) {\n            ${treeParentJavaType} parentId = vo.get${treeParentCapField}();\n            Long parentKey = parentId == null ? null : Long.valueOf(String.valueOf(parentId));\n            ${className}VO parent = parentKey == null ? null : index.get(parentKey);\n            if (parent == null || parent == vo) {\n                roots.add(vo);\n            } else {\n                parent.getChildren().add(vo);\n            }\n        }\n        return roots;\n    }\n</#if>\n<#if hasChild>\n    @Override\n    @Transactional(rollbackFor = Exception.class)\n    public void saveWithChildren(${className}SaveDTO master<#list children as child>,\n                                 List<${child.className}SaveDTO> ${child.varName}Rows</#list>) {\n        ${className} entity = new ${className}();\n        BeanUtils.copyProperties(master, entity);\n        saveOrUpdate(entity);\n<#list children as child>\n        replace${child.className}Rows(entity.getId(), ${child.varName}Rows);\n</#list>\n    }\n<#list children as child>\n    /**\n     * ${child.comment} 全量替换：先按外键逻辑删除旧行，再逐行插入，与主表同一事务。\n     * rows 为 null 表示本次提交未涉及该子表（不动），空列表表示清空。\n     */\n    private void replace${child.className}Rows(Long masterId, List<${child.className}SaveDTO> rows) {\n        if (masterId == null) {\n            return;\n        }\n        if (rows == null) {\n            return;\n        }\n        ${child.className}Mapper childMapper = ${child.varName}Mapper;\n        childMapper.delete(new LambdaQueryWrapper<${child.className}>()\n                .eq(${child.className}::get${child.fkCapField}, masterId));\n        for (${child.className}SaveDTO dto : rows) {\n            ${child.className} child = new ${child.className}();\n            BeanUtils.copyProperties(dto, child);\n            // 关键：旧行是逻辑删除（deleted=1，物理行仍在），沿用回传主键会撞 PRIMARY。\n            // 一律清空主键与审计字段，让雪花 ID 重新生成、时间交给自动填充。\n            child.setId(null);\n            child.setCreateTime(null);\n            child.setUpdateTime(null);\n            child.setCreateBy(null);\n            child.setUpdateBy(null);\n            child.set${child.fkCapField}(masterId);\n            childMapper.insert(child);\n<#list child.grandChildren as gc>\n            // 三级：这一行的下级也要跟着落库，外键指向刚插入的这行\n            save${gc.className}Rows(child.getId(), dto.get${gc.className}s());\n</#list>\n        }\n    }\n<#list child.grandChildren as gc>\n    /**\n     * ${gc.comment} 全量替换。抽成独立方法，避免保存主流程出现三层嵌套循环。\n     */\n    private void save${gc.className}Rows(Long parentId, List<${gc.className}SaveDTO> rows) {\n        if (parentId == null) {\n            return;\n        }\n        ${gc.className}Mapper mapper = ${gc.varName}Mapper;\n        mapper.delete(new LambdaQueryWrapper<${gc.className}>()\n                .eq(${gc.className}::get${gc.fkCapField}, parentId));\n        if (rows == null) {\n            return;\n        }\n        for (${gc.className}SaveDTO dto : rows) {\n            ${gc.className} row = new ${gc.className}();\n            BeanUtils.copyProperties(dto, row);\n            row.setId(null);\n            row.setCreateTime(null);\n            row.setUpdateTime(null);\n            row.setCreateBy(null);\n            row.setUpdateBy(null);\n            row.set${gc.fkCapField}(parentId);\n            mapper.insert(row);\n        }\n    }\n</#list>\n</#list>\n    /**\n     * V4.4 按删除级联模式删除主表（模式由生成时配置决定，三选一渲染）：\n     * 级联=先删各子表行（含三级）再删主行；阻止=任一子表还有有效行就拒删；不处理=仅删主行。\n     */\n    @Override\n    @Transactional(rollbackFor = Exception.class)\n    public void removeWithChildren(Long id) {\n<#if deleteCascadeBlock>\n<#list children as child>\n        Long ${child.varName}Count = ${child.varName}Mapper.selectCount(\n                new LambdaQueryWrapper<${child.className}>()\n                        .eq(${child.className}::get${child.fkCapField}, id));\n        if (${child.varName}Count != null && ${child.varName}Count > 0) {\n            throw new BusinessException(\"该${comment}下还有 \" + ${child.varName}Count + \" 条${child.comment}，请先清理明细再删除\");\n        }\n</#list>\n        removeById(id);\n<#elseif deleteCascadeOn>\n<#list children as child>\n        // ${child.comment}：先清三级，再按外键逻辑删除本级\n<#if child.grandChildren?size gt 0>\n        List<${child.className}> ${child.varName}Rows = ${child.varName}Mapper.selectList(\n                new LambdaQueryWrapper<${child.className}>()\n                        .eq(${child.className}::get${child.fkCapField}, id));\n        // 孙层按主键集合一次删：逐行 delete 会让「500 条明细」变成 500 条 SQL，全压在同一个事务里\n        List<Long> ${child.varName}Ids = ${child.varName}Rows.stream()\n                .map(${child.className}::getId).toList();\n<#list child.grandChildren as gc>\n        if (!${child.varName}Ids.isEmpty()) {\n            ${gc.varName}Mapper.delete(new LambdaQueryWrapper<${gc.className}>()\n                    .in(${gc.className}::get${gc.fkCapField}, ${child.varName}Ids));\n        }\n</#list>\n</#if>\n        ${child.varName}Mapper.delete(new LambdaQueryWrapper<${child.className}>()\n                .eq(${child.className}::get${child.fkCapField}, id));\n</#list>\n        removeById(id);\n<#else>\n        removeById(id);\n</#if>\n    }\n</#if>\n    // <gen:end key=\"service-body\">\n    // ===== 以下为手写区：自定义方法写在这里，重新生成不会被覆盖 =====\n}\n','${backendBase}/service/impl/${className}ServiceImpl.java',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:21',NULL,'2026-11-10 12:53:21'),(2120016941339930625,'pageDto','分页查询 DTO','backend','package ${pkg}.dto;\n\n<#if pageDtoHasBigDecimal>import java.math.BigDecimal;\n</#if>\n<#if pageDtoHasLocalDateTime>import java.time.LocalDateTime;\n</#if>\n<#if pageDtoHasLocalDate>import java.time.LocalDate;\n</#if>\n<#if pageDtoHasLocalTime>import java.time.LocalTime;\n</#if>\n<#if pageDtoHasImport>${\'\'}\n</#if>\nimport ${rootPkg}.common.page.PageQuery;\nimport lombok.Data;\nimport lombok.EqualsAndHashCode;\n\n/**\n * ${comment}分页查询 DTO\n */\n@Data\n@EqualsAndHashCode(callSuper = true)\npublic class ${className}PageDTO extends PageQuery {\n\n    // <gen:begin key=\"dto-fields\">\n<#list queryColumns as c>\n    private ${c.javaType} ${c.javaField};\n</#list>\n    // <gen:end key=\"dto-fields\">\n    // ===== 以下为手写区：写在 gen:end 之后的内容，重新生成不会被覆盖 =====\n}\n','${backendBase}/dto/${className}PageDTO.java',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:21',NULL,'2026-11-10 12:53:21'),(2120016941377679362,'saveDto','保存 DTO','backend','package ${pkg}.dto;\n\n<#if saveDtoHasBigDecimal>import java.math.BigDecimal;\n</#if>\n<#if saveDtoHasLocalDateTime>import java.time.LocalDateTime;\n</#if>\n<#if saveDtoHasLocalDate>import java.time.LocalDate;\n</#if>\n<#if saveDtoHasLocalTime>import java.time.LocalTime;\n</#if>\n<#if isChild && hasChild>import java.util.List;\n<#list children as g>import ${g.pkg}.dto.${g.className}SaveDTO;\n</#list></#if>\n<#if saveDtoHasImport>${\'\'}\n</#if>\n<#list validImports as imp>import ${imp};\n</#list>\n<#if validImports?size gt 0>${\'\'}\n</#if>\nimport lombok.Data;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n\n/**\n * ${comment}保存 DTO（新增/修改）\n */\n@Data\npublic class ${className}SaveDTO implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 1L;\n\n    // <gen:begin key=\"dto-fields\">\n    /**\n     * 主键，新增时为空\n     */\n    private Long id;\n\n<#list formColumns as c>\n<#if c.validJava?has_content>    ${c.validJava}\n</#if>    private ${c.javaType} ${c.javaField};\n</#list>\n<#if isChild && !masterFkInForm>\n    /**\n     * 所属主表 ID（由主表保存接口自动回填）\n     */\n    private Long ${masterFkField};\n</#if>\n<#if isChild && hasChild>\n<#list children as g>\n    /**\n     * 第三级明细：保存时随本级一起全量替换。\n     */\n    private List<${g.className}SaveDTO> ${g.varName}s;\n</#list>\n</#if>\n    // <gen:end key=\"dto-fields\">\n    // ===== 以下为手写区：写在 gen:end 之后的内容，重新生成不会被覆盖 =====\n}\n','${backendBase}/dto/${className}SaveDTO.java',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:21',NULL,'2026-11-10 12:53:21'),(2120016941444788226,'vo','列表 VO','backend','package ${pkg}.vo;\n\nimport lombok.Data;\nimport java.io.Serial;\nimport java.io.Serializable;\nimport java.time.LocalDateTime;\n<#if listHasBigDecimal>import java.math.BigDecimal;\n</#if>\n<#if listHasLocalDate>import java.time.LocalDate;\n</#if>\n<#if listHasLocalTime>import java.time.LocalTime;\n</#if>\n<#if genTree>import java.util.ArrayList;\nimport java.util.List;\n</#if>\n<#if isChild && hasChild>import java.util.List;\n<#list children as g>import ${g.pkg}.vo.${g.className}VO;\n</#list></#if>\n\n/**\n * ${comment} VO\n */\n@Data\npublic class ${className}VO implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 1L;\n\n    // <gen:begin key=\"vo-fields\">\n    private Long id;\n<#list listColumns as c>\n    private ${c.javaType} ${c.javaField};\n</#list>\n<#if genTree && !treeParentInList>\n    private ${treeParentJavaType} ${treeParentField};\n</#if>\n    private LocalDateTime createTime;\n    private LocalDateTime updateTime;\n<#if genTree>\n    /**\n     * 树形子节点\n     */\n    private List<${className}VO> children = new ArrayList<>();\n</#if>\n<#if isChild && hasChild>\n<#list children as g>\n    /**\n     * 第三级明细：详情接口一次性带出来，前端不用逐行再查\n     */\n    private List<${g.className}VO> ${g.varName}s;\n</#list>\n</#if>\n    // <gen:end key=\"vo-fields\">\n<#if hasMask>\n    // ===== 脱敏 getter（P1-1）：@Data 生成的 getter 被这里同名覆盖，序列化时自动脱敏 =====\n<#list maskColumns as c>\n    /**\n     * ${c.columnComment} 脱敏（${c.maskType}）\n     */\n    public ${c.javaType} get${c.capField}() {\n        return ${rootPkg}.common.util.MaskUtils.mask(this.${c.javaField}, \"${c.maskType}\");\n    }\n\n</#list>\n</#if>\n    // ===== 以下为手写区：写在 gen:end 之后的内容，重新生成不会被覆盖 =====\n}\n','${backendBase}/vo/${className}VO.java',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:22',NULL,'2026-11-10 12:53:22'),(2120016941503508482,'controller','Controller','backend','package ${pkg}.controller;\n\n<#if ctrlPageApi || hasChild || hasExcelExport>import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;\n</#if>\n<#if hasFlow>import ${rootPkg}.common.flow.FlowService;\n</#if>\n<#if ctrlPageApi || hasExcelExport>import com.baomidou.mybatisplus.extension.plugins.pagination.Page;\nimport ${pkg}.dto.${className}PageDTO;\n</#if>\n<#if ctrlAddApi || ctrlEditApi || hasChild>import ${pkg}.dto.${className}SaveDTO;\n</#if>\n<#if hasChild><#list children as child>import ${pkg}.dto.${child.className}SaveDTO;\nimport ${pkg}.entity.${child.className};\nimport ${pkg}.service.${child.className}Service;\nimport ${pkg}.vo.${child.className}VO;\n<#list child.grandChildren as gc>import ${pkg}.entity.${gc.className};\nimport ${pkg}.service.${gc.className}Service;\nimport ${pkg}.vo.${gc.className}VO;\n</#list>\n</#list></#if>\n<#-- Service 无条件注入：page/detail 等基础方法也要走 Service，\n     曾经按开关条件注入，开关全关时方法体还在、字段没了，生成产物直接编译失败 -->\nimport ${pkg}.service.${className}Service;\nimport ${pkg}.entity.${className};\nimport ${pkg}.vo.${className}VO;\nimport ${rootPkg}.common.result.Result;\n<#if hasRef || hasExcelImport || hasUnique>import ${rootPkg}.common.exception.BusinessException;\n</#if>\n<#if genLog>import ${rootPkg}.common.log.Log;\n</#if>\n<#if hasRef>import org.springframework.jdbc.core.JdbcTemplate;\n</#if>\nimport io.swagger.v3.oas.annotations.Operation;\nimport io.swagger.v3.oas.annotations.tags.Tag;\n<#if ctrlValid>import jakarta.validation.Valid;\n</#if>\n<#if ctrlAnyApi || genTree || hasChild>import org.springframework.beans.BeanUtils;\n</#if>\n<#if ctrlAnyApi || genTree || hasChild || hasUnique || hasFlow || hasRef>import org.springframework.beans.factory.annotation.Autowired;\n</#if>\n<#if (ctrlAnyApi || genTree || hasChild) && ctrlPageApi>import org.springframework.util.StringUtils;\n</#if>\n<#if hasExcelExport && !ctrlPageApi>import org.springframework.util.StringUtils;\n</#if>\n<#if ctrlDeleteApi>import org.springframework.web.bind.annotation.DeleteMapping;\n</#if>\n<#if ctrlDetailApi || genTree || hasRef || hasExcelExport || hasUnique>import org.springframework.web.bind.annotation.GetMapping;\n</#if>\nimport org.springframework.web.bind.annotation.PathVariable;\n<#if ctrlPageApi || ctrlAddApi || hasChild>import org.springframework.web.bind.annotation.PostMapping;\n</#if>\n<#if ctrlEditApi>import org.springframework.web.bind.annotation.PutMapping;\n</#if>\n<#if ctrlPageApi || ctrlAddApi || ctrlEditApi || hasChild>import org.springframework.web.bind.annotation.RequestBody;\n</#if>\nimport org.springframework.web.bind.annotation.RequestMapping;\n<#if genTree || hasRef || hasExcelImport || hasUnique>import org.springframework.web.bind.annotation.RequestParam;\n</#if>\nimport org.springframework.web.bind.annotation.RestController;\n<#if ctrlPageApi || genTree || hasChild || hasExcelImport>import java.util.ArrayList;\n</#if>\n<#if ctrlPageApi || genTree || hasChild || hasRef>import java.util.List;\n</#if>\n<#if hasRef || hasExcelImport || hasChild>import java.util.LinkedHashMap;\nimport java.util.Map;\n</#if>\n<#if hasExcelExport || hasExcelImport>import org.apache.poi.ss.usermodel.Cell;\nimport org.apache.poi.ss.usermodel.Row;\nimport org.apache.poi.ss.usermodel.Sheet;\nimport org.apache.poi.ss.usermodel.Workbook;\nimport org.apache.poi.xssf.usermodel.XSSFWorkbook;\nimport org.springframework.http.HttpHeaders;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.bind.annotation.RequestParam;\nimport org.springframework.web.multipart.MultipartFile;\nimport java.io.ByteArrayOutputStream;\nimport java.io.IOException;\nimport java.math.BigDecimal;\nimport java.net.URLEncoder;\nimport java.nio.charset.StandardCharsets;\nimport java.time.LocalDate;\nimport java.time.LocalDateTime;\n</#if>\n<#if hasExcelImport && !(ctrlAnyApi || genTree || hasChild)>import org.springframework.jdbc.core.JdbcTemplate;\n</#if>\n\n/**\n * ${comment} Controller\n */\n@Tag(name = \"${comment}管理\", description = \"${comment}管理\")\n@RestController\n@RequestMapping(\"/${moduleName}\")\npublic class ${className}Controller {\n${\'\'}\n    // Service 注入无条件保留（理由见 import 区注释）\n    @Autowired\n    private ${className}Service ${varName}Service;\n<#if hasChild><#list children as child>    @Autowired\n    private ${child.className}Service ${child.varName}Service;\n<#-- 孙表 Service：详情接口装配三级明细要用，漏注入生成的 Controller 编译不过 -->\n<#list child.grandChildren as gc>    @Autowired\n    private ${gc.className}Service ${gc.varName}Service;\n</#list>\n</#list></#if>\n<#if hasFlow>    @Autowired\n    private FlowService flowService;\n</#if>\n<#if hasDictColumn>\n    @Autowired\n    private ${rootPkg}.common.util.DictTexts dictTexts;\n</#if>\n    // <gen:begin key=\"controller-body\">\n<#if hasRef>\n    @Autowired\n    private JdbcTemplate jdbcTemplate;\n</#if>\n<#if isMiddle && relationKeys?size gte 2>${\'\'}\n@Operation(summary = \"${comment}：按一个外键取另一侧的全部值（多选回显用）\")\n@GetMapping(\"/bind-values\")\npublic Result<List<Long>> bindValues(@RequestParam(\"column\") String column,\n                                     @RequestParam(\"id\") Long id) {\n    // column 只接受本表的两个外键列，其余一律拒绝，杜绝把任意列拼进 SQL\n    boolean left = \"${relationKeys[0].dbField}\".equalsIgnoreCase(column);\n    boolean right = \"${relationKeys[1].dbField}\".equalsIgnoreCase(column);\n    if (!left && !right) {\n        throw new BusinessException(400, \"不是合法的关联列：\" + column);\n    }\n    // 传入的是左键就返右键的集合，反之亦然；两边都按同一个 id 过滤\n    // Lambda 选择在 Java 侧做（模板里写三元会被 FreeMarker 当字符串），两条分支各自编译期确定\n    List<${className}> rows = left\n            ? ${varName}Service.list(new LambdaQueryWrapper<${className}>()\n                    .eq(${className}::get${relationKeys[0].capProp}, id))\n            : ${varName}Service.list(new LambdaQueryWrapper<${className}>()\n                    .eq(${className}::get${relationKeys[1].capProp}, id));\n    List<Long> values = new ArrayList<>();\n    for (${className} row : rows) {\n        Object v = left ? row.get${relationKeys[1].capProp}() : row.get${relationKeys[0].capProp}();\n        if (v != null) {\n            values.add(Long.valueOf(String.valueOf(v)));\n        }\n    }\n    return Result.ok(values);\n}\n</#if>\n<#if ctrlPageApi>${\'\'}\n@Operation(summary = \"分页查询${comment}\")\n@PostMapping(\"/page\")\npublic Result<Page<${className}VO>> page(@RequestBody ${className}PageDTO dto) {\n    Page<${className}> page = new Page<>(dto.getPageNum(), dto.getPageSize());\n    LambdaQueryWrapper<${className}> wrapper = new LambdaQueryWrapper<>();\n<#list queryColumns as c>\n        wrapper.${c.queryOp}(<#if c.isString>StringUtils.hasText(dto.get${c.capField}())<#else>dto.get${c.capField}() != null</#if>, ${className}::get${c.capField}, dto.get${c.capField}());\n</#list>\n        wrapper.orderByDesc(${className}::getId);\n    ${varName}Service.page(page, wrapper);\n    Page<${className}VO> voPage = new Page<>();\n    BeanUtils.copyProperties(page, voPage);\n    List<${className}VO> records = page.getRecords().stream()\n            .map(e -> {\n                ${className}VO vo = new ${className}VO();\n                BeanUtils.copyProperties(e, vo);\n                return vo;\n            })\n            .toList();\n    voPage.setRecords(records);\n    return Result.ok(voPage);\n}\n</#if>\n<#if genTree>${\'\'}\n@Operation(summary = \"${comment}树形列表\")\n@GetMapping(\"/tree\")\npublic Result<List<${className}VO>> tree() {\n    return Result.ok(${varName}Service.tree());\n}\n</#if>\n<#if hasRef>${\'\'}\n@Operation(summary = \"关联下拉选项（通用，按 ref_table 远程搜索）\")\n@GetMapping(\"/options\")\npublic Result<List<Map<String, Object>>> options(@RequestParam(\"refTable\") String refTable,\n                                                @RequestParam(value = \"label\", required = false) String label,\n                                                @RequestParam(value = \"keyword\", required = false) String keyword) {\n    if (refTable == null || !refTable.matches(\"[A-Za-z0-9_]+\")) {\n        throw new BusinessException(400, \"非法关联表名\");\n    }\n    String labelCol = label == null || !label.matches(\"[A-Za-z0-9_]+\") ? \"name\" : label;\n    String base = \"SELECT id, \" + labelCol + \" AS label FROM \" + refTable;\n    String like = keyword == null || keyword.isBlank() ? null : \"%\" + keyword.trim() + \"%\";\n    // 无关键字是「列表页翻译 ID 为名称」，要一次拉够；有关键字是下拉搜索，20 条足够\n    int limit = like == null ? 500 : 20;\n    String sql = base + \" WHERE deleted = 0\" + (like == null ? \"\" : \" AND \" + labelCol + \" LIKE ?\")\n            + \" ORDER BY id DESC LIMIT \" + limit;\n    try {\n        return Result.ok(like == null\n                ? jdbcTemplate.queryForList(sql)\n                : jdbcTemplate.queryForList(sql, like));\n    } catch (Exception e) {\n        // 关联表没有 deleted 列（如关联表）时降级为不带软删条件\n        String fallback = base + (like == null ? \"\" : \" WHERE \" + labelCol + \" LIKE ?\")\n                + \" ORDER BY id DESC LIMIT \" + limit;\n        return Result.ok(like == null\n                ? jdbcTemplate.queryForList(fallback)\n                : jdbcTemplate.queryForList(fallback, like));\n    }\n}\n</#if>\n<#if hasChild>${\'\'}\n@Operation(summary = \"主表详情（含${childCount}张子表明细）\")\n@GetMapping(\"/{id}/with-children\")\npublic Result<Map<String, Object>> detailWithChildren(@PathVariable(\"id\") Long id) {\n    ${className} entity = ${varName}Service.getById(id);\n    Map<String, Object> data = new LinkedHashMap<>();\n    if (entity == null) {\n        return Result.ok(data);\n    }\n    ${className}VO masterVo = new ${className}VO();\n    BeanUtils.copyProperties(entity, masterVo);\n    List<Map<String, Object>> children = new ArrayList<>();\n<#list children as child>\n    // 子表：${child.comment}（整棵树一次返回，避免前端逐行发请求）\n    Map<String, Object> ${child.varName}Group = new LinkedHashMap<>();\n    ${child.varName}Group.put(\"key\", \"${child.varName}\");\n    ${child.varName}Group.put(\"tableName\", \"${child.tableName}\");\n    ${child.varName}Group.put(\"comment\", \"${child.comment}\");\n    List<${child.className}VO> ${child.varName}List = new ArrayList<>();\n    for (${child.className} row : ${child.varName}Service.list(\n            new LambdaQueryWrapper<${child.className}>().eq(${child.className}::get${child.fkCapField}, id))) {\n        ${child.className}VO childVo = new ${child.className}VO();\n        BeanUtils.copyProperties(row, childVo);\n<#list child.grandChildren as gc>\n        // 三级：按子表主键再查一层\n        List<${gc.className}VO> ${gc.varName}List = new ArrayList<>();\n        for (${gc.className} g : ${gc.varName}Service.list(\n                new LambdaQueryWrapper<${gc.className}>()\n                        .eq(${gc.className}::get${gc.fkCapField}, row.getId()))) {\n            ${gc.className}VO gVo = new ${gc.className}VO();\n            BeanUtils.copyProperties(g, gVo);\n            ${gc.varName}List.add(gVo);\n        }\n        childVo.set${gc.className}s(${gc.varName}List);\n</#list>\n        ${child.varName}List.add(childVo);\n    }\n    ${child.varName}Group.put(\"rows\", ${child.varName}List);\n    children.add(${child.varName}Group);\n</#list>\n    data.put(\"master\", masterVo);\n    data.put(\"children\", children);\n    return Result.ok(data);\n}\n\n@Operation(summary = \"保存${comment}（主表 + 子表同事务；子表字段为 null 表示不动，空列表表示清空）\")\n@PostMapping(\"/save-with-children\")\npublic Result<Void> saveWithChildren(<#if ctrlValid>@Valid </#if>@RequestBody WithChildrenDTO dto) {\n    ${varName}Service.saveWithChildren(dto.getMaster()<#list children as child>,\n                                       dto.get${child.varName?cap_first}Rows()</#list>);\n    return Result.ok();\n}\n\n/**\n * 主子表保存入参：每张子表一个可空字段（null=不动该子表，[]=清空该子表）\n */\n@lombok.Data\npublic static class WithChildrenDTO {\n\n    private ${className}SaveDTO master;\n<#list children as child>\n\n    private List<${child.className}SaveDTO> ${child.varName}Rows;\n</#list>\n}\n</#if>\n<#if hasExcelExport && !isMiddle>${\'\'}\n@Operation(summary = \"导出${comment} Excel（按查询条件过滤；不传条件导出全部）\")\n@PostMapping(\"/export\")\npublic ResponseEntity<byte[]> export(@RequestBody(required = false) ${className}PageDTO query) throws IOException {\n    // 复用列表页的筛选口径：导出的行必须和用户在页面上看到的一致，\n    // 否则「筛出 20 条、导出 2000 条」会被当成 bug。\n    LambdaQueryWrapper<${className}> wrapper = new LambdaQueryWrapper<>();\n    if (query != null) {\n<#list queryColumns as c>\n        wrapper.${c.queryOp}(<#if c.isString>StringUtils.hasText(query.get${c.capField}())<#else>query.get${c.capField}() != null</#if>, ${className}::get${c.capField}, query.get${c.capField}());\n</#list>\n    }\n    wrapper.orderByDesc(${className}::getId);\n    List<${className}> rows = ${varName}Service.list(wrapper);\n    try (Workbook wb = new XSSFWorkbook(); ByteArrayOutputStream bos = new ByteArrayOutputStream()) {\n        Sheet sheet = wb.createSheet(\"${comment}\");\n        Row header = sheet.createRow(0);\n<#list excelColumns as c>\n        header.createCell(${c?index}).setCellValue(\"${c.commentLabel}\");\n</#list>\n        int rowIndex = 1;\n        for (${className} e : rows) {\n            Row row = sheet.createRow(rowIndex++);\n<#list excelColumns as c>\n<#if c.hasDict>\n            // 字典列导出中文标签，与页面显示一致；null 写空串，不能落成字面量 \"null\"\n            row.createCell(${c?index}).setCellValue(e.get${c.capField}() == null ? \"\" : dictTexts.label(\"${c.dictType}\", String.valueOf(e.get${c.capField}())));\n<#elseif c.isNumber>\n            row.createCell(${c?index}).setCellValue(cellNum(e.get${c.capField}()));\n<#else>\n            row.createCell(${c?index}).setCellValue(cellText(e.get${c.capField}()));\n</#if>\n</#list>\n        }\n        wb.write(bos);\n        String fileName = URLEncoder.encode(\"${comment}.xlsx\", StandardCharsets.UTF_8).replace(\"+\", \"%20\");\n        return ResponseEntity.ok()\n                .header(HttpHeaders.CONTENT_DISPOSITION, \"attachment; filename*=UTF-8\'\'\" + fileName)\n                .contentType(MediaType.APPLICATION_OCTET_STREAM)\n                .body(bos.toByteArray());\n    }\n}\n</#if>\n<#if hasExcelImport>${\'\'}\n@Operation(summary = \"导入${comment} Excel（首行为表头，逐行独立事务）\")\n<#if genLog>@Log(title = \"${comment}\", type = \"IMPORT\", saveParam = false)\n</#if>@PostMapping(\"/import\")\npublic Result<Map<String, Object>> importExcel(@RequestParam(\"file\") MultipartFile file) throws IOException {\n    if (file == null || file.isEmpty()) {\n        throw new BusinessException(400, \"请选择要导入的文件\");\n    }\n    int success = 0;\n    int skipped = 0;\n    List<Map<String, Object>> failed = new ArrayList<>();\n    try (Workbook wb = new XSSFWorkbook(file.getInputStream())) {\n        Sheet sheet = wb.getSheetAt(0);\n        Row header = sheet.getRow(0);\n        if (header == null) {\n            throw new BusinessException(400, \"表头为空，无法导入\");\n        }\n        Map<String, Integer> index = new LinkedHashMap<>();\n        for (int i = 0; i < header.getLastCellNum(); i++) {\n            index.put(cellText(header.getCell(i)).trim(), i);\n        }\n        // 表头缺失的列直接提示出来，避免用户以为导入了却全是空值\n        List<String> missing = new ArrayList<>();\n<#list excelImportColumns as c>\n        Integer col${c.capField} = index.get(\"${c.commentLabel}\");\n        if (col${c.capField} == null) {\n            missing.add(\"${c.commentLabel}\");\n        }\n</#list>\n        if (!missing.isEmpty()) {\n            throw new BusinessException(400, \"表头缺少列：\" + String.join(\"、\", missing));\n        }\n        for (int r = 1; r <= sheet.getLastRowNum(); r++) {\n            Row row = sheet.getRow(r);\n            if (row == null || isBlankRow(row)) {\n                continue;\n            }\n            // 每行独立事务：单行失败只回滚该行，不影响已成功的行\n            try {\n                ${className} entity = new ${className}();\n<#list excelImportColumns as c>\n                entity.set${c.capField}(<#if c.isString>text(row, col${c.capField})<#elseif c.javaType == \"Integer\">parseInteger(row, col${c.capField})<#elseif c.javaType == \"Long\">parseLong(row, col${c.capField})<#elseif c.javaType == \"BigDecimal\">parseDecimal(row, col${c.capField})<#elseif c.javaType == \"LocalDate\">parseDate(row, col${c.capField})<#elseif c.javaType == \"LocalDateTime\">parseDateTime(row, col${c.capField})<#else>text(row, col${c.capField})</#if>);\n</#list>\n                List<String> rowErrors = validateImportRow(entity, r + 1);\n                if (!rowErrors.isEmpty()) {\n                    Map<String, Object> err = new LinkedHashMap<>();\n                    err.put(\"row\", r + 1);\n                    err.put(\"msg\", String.join(\"；\", rowErrors));\n                    failed.add(err);\n                    continue;\n                }\n                if (saveImportRow(entity)) {\n                    success++;\n                } else {\n                    skipped++;\n                }\n            } catch (Exception ex) {\n                Map<String, Object> err = new LinkedHashMap<>();\n                err.put(\"row\", r + 1);\n                err.put(\"msg\", rootMessage(ex));\n                failed.add(err);\n            }\n        }\n    }\n    Map<String, Object> data = new LinkedHashMap<>();\n    data.put(\"total\", success + skipped + failed.size());\n    data.put(\"success\", success);\n    data.put(\"skipped\", skipped);\n    data.put(\"failedCount\", failed.size());\n    data.put(\"failed\", failed);\n    return Result.ok(data);\n}\n\n@Operation(summary = \"下载${comment}导入模板（表头 + 填写说明行）\")\n@GetMapping(\"/import-template\")\npublic ResponseEntity<byte[]> importTemplate() throws IOException {\n    try (Workbook wb = new XSSFWorkbook(); ByteArrayOutputStream bos = new ByteArrayOutputStream()) {\n        Sheet sheet = wb.createSheet(\"${comment}导入模板\");\n        // 第 1 行是表头，必须与 /import 的表头匹配逻辑完全一致，否则下载的模板自己导不回去。\n        // 导出表头/导入定位/本模板三处统一 commentLabel（剥枚举说明），改一处必须同步三处\n        Row header = sheet.createRow(0);\n<#list excelImportColumns as c>\n        header.createCell(${c?index}).setCellValue(\"${c.commentLabel}\");\n</#list>\n        // 第 2 行是填写说明。导入逻辑按列名匹配表头、逐行校验，\n        // 这一行必然过不了校验而被记进 failed，所以文案里直接写「请删除本行」。\n        // 不放下拉/数据验证：POI 的 DataValidation 需要额外依赖，且模板只起提示作用。\n        Row hint = sheet.createRow(1);\n<#list excelImportColumns as c>\n        hint.createCell(${c?index}).setCellValue(\"【说明行，导入前请删除】<#if c.isRequired>必填<#else>选填</#if><#if (c.maxLen gt 0)>，不超过${c.maxLen}字</#if>\");\n</#list>\n<#list excelImportColumns as c>\n        sheet.setColumnWidth(${c?index}, Math.min(${c.colWidth}, 60) * 256);\n</#list>\n        wb.write(bos);\n        String fileName = URLEncoder.encode(\"${comment}导入模板.xlsx\", StandardCharsets.UTF_8).replace(\"+\", \"%20\");\n        return ResponseEntity.ok()\n                .header(HttpHeaders.CONTENT_DISPOSITION, \"attachment; filename*=UTF-8\'\'\" + fileName)\n                .contentType(MediaType.APPLICATION_OCTET_STREAM)\n                .body(bos.toByteArray());\n    }\n}\n\n@Operation(summary = \"下载导入失败明细\")\n@GetMapping(\"/import/failed\")\npublic ResponseEntity<byte[]> downloadImportFailed(@RequestParam(\"msg\") List<String> messages) throws IOException {\n    try (Workbook wb = new XSSFWorkbook(); ByteArrayOutputStream bos = new ByteArrayOutputStream()) {\n        Sheet sheet = wb.createSheet(\"导入失败明细\");\n        Row head = sheet.createRow(0);\n        head.createCell(0).setCellValue(\"行号\");\n        head.createCell(1).setCellValue(\"失败原因\");\n        int r = 1;\n        for (String msg : messages) {\n            Row row = sheet.createRow(r);\n            String[] parts = msg.split(\"\\\\|\", 2);\n            row.createCell(0).setCellValue(parts.length > 1 ? parts[0] : String.valueOf(r));\n            row.createCell(1).setCellValue(parts.length > 1 ? parts[1] : msg);\n            r++;\n        }\n        sheet.setColumnWidth(0, 10 * 256);\n        sheet.setColumnWidth(1, 60 * 256);\n        wb.write(bos);\n        String fileName = URLEncoder.encode(\"${comment}导入失败明细.xlsx\", StandardCharsets.UTF_8).replace(\"+\", \"%20\");\n        return ResponseEntity.ok()\n                .header(HttpHeaders.CONTENT_DISPOSITION, \"attachment; filename*=UTF-8\'\'\" + fileName)\n                .contentType(MediaType.APPLICATION_OCTET_STREAM)\n                .body(bos.toByteArray());\n    }\n}\n\n/**\n * 逐行业务校验：只校验「必填」与「长度」，其余交给数据库约束。\n * 返回空列表代表该行可入库。\n */\nprivate List<String> validateImportRow(${className} entity, int rowNum) {\n    List<String> errors = new ArrayList<>();\n<#list excelImportColumns as c>\n<#if c.isRequired>\n    if (<#if c.isString>entity.get${c.capField}() == null || entity.get${c.capField}().isBlank()<#else>entity.get${c.capField}() == null</#if>) {\n        errors.add(\"${c.commentLabel}不能为空\");\n    }\n</#if>\n<#if c.isString && c.maxLen gt 0>\n    if (entity.get${c.capField}() != null && entity.get${c.capField}().length() > ${c.maxLen}) {\n        errors.add(\"${c.commentLabel}长度不能超过${c.maxLen}个字符\");\n    }\n</#if>\n</#list>\n    return errors;\n}\n\n/**\n * 保存单行。返回 false 表示命中唯一约束被跳过（视为已存在，不算失败）。\n */\nprivate boolean saveImportRow(${className} entity) {\n    try {\n        return ${varName}Service.save(entity);\n    } catch (org.springframework.dao.DuplicateKeyException ex) {\n        return false;\n    }\n}\n\nprivate static String rootMessage(Throwable ex) {\n    Throwable cur = ex;\n    while (cur.getCause() != null && cur.getCause() != cur) {\n        cur = cur.getCause();\n    }\n    String msg = cur.getMessage();\n    if (msg == null || msg.isBlank()) {\n        return \"数据格式不正确\";\n    }\n    // 数据库原始报错太长，截断到可读长度\n    return msg.length() > 200 ? msg.substring(0, 200) + \"...\" : msg;\n}\n\nprivate static boolean isBlankRow(Row row) {\n    for (int i = 0; i < row.getLastCellNum(); i++) {\n        if (!cellText(row.getCell(i)).isBlank()) {\n            return false;\n        }\n    }\n    return true;\n}\n</#if>\n<#if ctrlDetailApi>${\'\'}\n@Operation(summary = \"根据ID查询${comment}\")\n@GetMapping(\"/{id}\")\npublic Result<${className}VO> getById(@PathVariable(\"id\") Long id) {\n    ${className} entity = ${varName}Service.getById(id);\n    if (entity == null) {\n        return Result.ok(null);\n    }\n    ${className}VO vo = new ${className}VO();\n    BeanUtils.copyProperties(entity, vo);\n    return Result.ok(vo);\n}\n</#if>\n<#if ctrlAddApi>${\'\'}\n@Operation(summary = \"新增${comment}\")\n<#if genLog>@Log(title = \"${comment}\", type = \"INSERT\")\n</#if>@PostMapping\npublic Result<Void> add(<#if ctrlValid>@Valid </#if>@RequestBody ${className}SaveDTO dto) {\n<#if hasUnique>\n    checkUnique(dto, null);\n</#if>\n    ${className} entity = new ${className}();\n    BeanUtils.copyProperties(dto, entity);\n    ${varName}Service.save(entity);\n    return Result.ok();\n}\n</#if>\n<#if ctrlEditApi>${\'\'}\n@Operation(summary = \"修改${comment}\")\n<#if genLog>@Log(title = \"${comment}\", type = \"UPDATE\")\n</#if>@PutMapping\npublic Result<Void> update(<#if ctrlValid>@Valid </#if>@RequestBody ${className}SaveDTO dto) {\n<#if hasUnique>\n    checkUnique(dto, dto.getId());\n</#if>\n    ${className} entity = new ${className}();\n    BeanUtils.copyProperties(dto, entity);\n    ${varName}Service.updateById(entity);\n    return Result.ok();\n}\n</#if>\n<#if ctrlDeleteApi>${\'\'}\n@Operation(summary = \"删除${comment}<#if hasChild>（按表的级联模式处理明细）</#if>\")\n<#if genLog>@Log(title = \"${comment}\", type = \"DELETE\")\n</#if>@DeleteMapping(\"/{id}\")\npublic Result<Void> delete(@PathVariable(\"id\") Long id) {\n<#if hasChild>\n    // V4.4：主子表走 removeWithChildren（级联/阻止/不处理由生成配置决定），不能直接 removeById 留孤儿明细\n    ${varName}Service.removeWithChildren(id);\n<#else>\n    ${varName}Service.removeById(id);\n</#if>\n    return Result.ok();\n}\n</#if>\n    // <gen:end key=\"controller-body\">\n<#if hasFlow>${\'\'}\n    // ==================== P3-3 审批流（流程：${flowCode}） ====================\n\n    @Operation(summary = \"提交${comment}审批\")\n    <#if genLog>@Log(title = \"${comment}\", type = \"SUBMIT\")\n    </#if>@PostMapping(\"/flow/submit/{id}\")\n    public Result<Void> flowSubmit(@PathVariable(\"id\") Long id) {\n        flowService.submit(\"${flowCode}\", id, null);\n        return Result.ok();\n    }\n\n    @Operation(summary = \"审批通过${comment}\")\n    @PostMapping(\"/flow/approve/{id}\")\n    public Result<Void> flowApprove(@PathVariable(\"id\") Long id,\n                                    @RequestParam(value = \"comment\", required = false) String comment) {\n        flowService.approve(\"${flowCode}\", id, comment);\n        return Result.ok();\n    }\n\n    @Operation(summary = \"驳回${comment}\")\n    @PostMapping(\"/flow/reject/{id}\")\n    public Result<Void> flowReject(@PathVariable(\"id\") Long id,\n                                   @RequestParam(value = \"comment\", required = false) String comment) {\n        flowService.reject(\"${flowCode}\", id, comment);\n        return Result.ok();\n    }\n\n    @Operation(summary = \"${comment}审批记录\")\n    @GetMapping(\"/flow/records/{id}\")\n    public Result<List<Map<String, Object>>> flowRecords(@PathVariable(\"id\") Long id) {\n        List<Map<String, Object>> list = new ArrayList<>();\n        for (${rootPkg}.common.flow.FlowRecord r : flowService.records(\"${flowCode}\", id)) {\n            Map<String, Object> m = new LinkedHashMap<>();\n            m.put(\"action\", r.getAction());\n            m.put(\"fromStatus\", r.getFromStatus());\n            m.put(\"toStatus\", r.getToStatus());\n            m.put(\"comment\", r.getComment());\n            m.put(\"operName\", r.getOperName());\n            m.put(\"operTime\", r.getOperTime());\n            list.add(m);\n        }\n        return Result.ok(list);\n    }\n</#if>\n<#if hasUnique>${\'\'}\n    // ==================== P1-3 唯一性校验 ====================\n\n    @Operation(summary = \"字段唯一性校验（前端异步查重用）\")\n    @GetMapping(\"/check-unique\")\n    public Result<Boolean> checkUniqueField(@RequestParam(\"field\") String field,\n                                            @RequestParam(\"value\") String value,\n                                            @RequestParam(value = \"excludeId\", required = false) Long excludeId) {\n        <#list uniqueColumns as c>\n        if (\"${c.javaField}\".equals(field)) {\n            return Result.ok(countBy(\"${c.dbField}\", value, excludeId) > 0);\n        }\n        </#list>\n        return Result.ok(false);\n    }\n\n    /**\n     * 保存前兜底校验：前端异步校验只是体验优化，绕过接口直接调保存时这里必须拦住。\n     * 单列 unique 逐列判断；多列 unique 联合判断（同时相等才算重复）。\n     */\n    private void checkUnique(${className}SaveDTO dto, Long excludeId) {\n        <#if hasSingleUnique>\n        <#list uniqueColumns as c>\n        if (dto.get${c.capField}() != null && !String.valueOf(dto.get${c.capField}()).isBlank()\n                && countBy(\"${c.dbField}\", String.valueOf(dto.get${c.capField}()), excludeId) > 0) {\n            throw new BusinessException(400, \"${c.commentLabel}已存在\");\n        }\n        </#list>\n        <#else>\n        boolean anyNull = <#list uniqueColumns as c>dto.get${c.capField}() == null || </#list>false;\n        if (!anyNull) {\n            com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper<${className}> wrapper =\n                    new com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper<>();\n            <#list uniqueColumns as c>\n            wrapper.eq(${className}::get${c.capField}, dto.get${c.capField}());\n            </#list>\n            if (excludeId != null) {\n                wrapper.ne(${className}::getId, excludeId);\n            }\n            if (${varName}Service.count(wrapper) > 0) {\n                throw new BusinessException(400, \"<#list uniqueColumns as c>${c.commentLabel}<#if c_has_next>+</#if></#list>组合已存在\");\n            }\n        }\n        </#if>\n    }\n\n    /**\n     * 按列名统计重复条数。列名来自生成期常量，不存在拼接用户输入的风险。\n     */\n    private long countBy(String column, String value, Long excludeId) {\n        com.baomidou.mybatisplus.core.conditions.query.QueryWrapper<${className}> wrapper =\n                new com.baomidou.mybatisplus.core.conditions.query.QueryWrapper<>();\n        wrapper.eq(column, value);\n        if (excludeId != null) {\n            wrapper.ne(\"id\", excludeId);\n        }\n        return ${varName}Service.count(wrapper);\n    }\n</#if>\n<#if hasExcelExport || hasExcelImport>${\'\'}\n    private static String cellText(Object value) {\n        return value == null ? \"\" : String.valueOf(value);\n    }\n\n    private static double cellNum(Object value) {\n        return value instanceof Number number ? number.doubleValue() : 0D;\n    }\n\n    private static String text(Row row, Integer col) {\n        if (col == null || row == null) {\n            return null;\n        }\n        String value = cellText(row.getCell(col)).trim();\n        return value.isEmpty() ? null : value;\n    }\n<#if hasExcelImport>${\'\'}\n    private static Integer parseInteger(Row row, Integer col) {\n        String value = text(row, col);\n        return value == null ? null : new BigDecimal(value).intValue();\n    }\n\n    private static Long parseLong(Row row, Integer col) {\n        String value = text(row, col);\n        return value == null ? null : new BigDecimal(value).longValue();\n    }\n\n    private static BigDecimal parseDecimal(Row row, Integer col) {\n        String value = text(row, col);\n        return value == null ? null : new BigDecimal(value);\n    }\n\n    private static LocalDate parseDate(Row row, Integer col) {\n        String value = text(row, col);\n        return value == null ? null : LocalDate.parse(value.replace(\"/\", \"-\"));\n    }\n\n    private static LocalDateTime parseDateTime(Row row, Integer col) {\n        String value = text(row, col);\n        return value == null ? null : LocalDateTime.parse(value.replace(\"/\", \"-\").replace(\" \", \"T\"));\n    }\n</#if>\n</#if>\n    // ===== 以下为手写区：自定义接口写在这里，重新生成不会被覆盖 =====\n}\n','${backendBase}/controller/${className}Controller.java',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:22',NULL,'2026-11-10 12:53:22'),(2120016941650309122,'apiJs','前端 api.js','frontend','import request, { toPageData } from \'@/utils/request\'\n\n// ${comment}接口：${tableName}<#if isMicro>（经平台网关 /${moduleName}）<#elseif gatewayPrefix?? && gatewayPrefix != \'\'>（经网关 /api/${gatewayPrefix}）</#if>\n// <gen:begin key=\"api-fns\">\n<#if genPageApi>function toPageQuery(params) {\n  const { page, size, ...query } = params || {}\n  return { pageNum: page || 1, pageSize: size || 10, ...query }\n}\n</#if>\n<#if genPageApi>export function get${className}List(params) {\n  return request({\n    url: \'${apiBase}/page\',\n    method: \'post\',\n    data: toPageQuery(params)\n  }).then(toPageData)\n}\n</#if>\n<#if genTree>export function get${className}Tree() {\n  return request({\n    url: \'${apiBase}/tree\',\n    method: \'get\'\n  })\n}\n</#if>\n<#if hasRef>export function get${className}Options(refTable, label, keyword) {\n  return request({\n    url: \'${apiBase}/options\',\n    method: \'get\',\n    params: { refTable, label, keyword }\n  })\n}\n</#if>\n<#if hasChild>export function get${className}WithChildren(id) {\n  return request({\n    url: `${apiBase}/${\'$\'}{id}/with-children`,\n    method: \'get\'\n  })\n}\n\n// payload = { master, ...各子表 {childVar}Rows }；子表字段 null=不动，[]=清空\nexport function save${className}WithChildren(payload) {\n  return request({\n    url: \'${apiBase}/save-with-children\',\n    method: \'post\',\n    data: payload\n  })\n}\n</#if>\n<#if hasExcelExport>export function export${className}(params) {\n  return request({\n    url: \'${apiBase}/export\',\n    method: \'post\',\n    data: params || {},\n    responseType: \'blob\'\n  })\n}\n</#if>\n<#if hasExcelImport>export function import${className}(file) {\n  const formData = new FormData()\n  formData.append(\'file\', file)\n  return request({\n    url: \'${apiBase}/import\',\n    method: \'post\',\n    data: formData,\n    headers: { \'Content-Type\': \'multipart/form-data\' }\n  })\n}\n\n// 空白导入模板（表头 + 说明行），让用户不用猜列名\nexport function download${className}Template() {\n  return request({\n    url: \'${apiBase}/import-template\',\n    method: \'get\',\n    responseType: \'blob\'\n  })\n}\n</#if>\n<#if genDetailApi>export function get${className}Detail(id) {\n  return request({\n    url: `${apiBase}/${\'$\'}{id}`,\n    method: \'get\'\n  })\n}\n</#if>\n<#if genAddApi>export function create${className}(data) {\n  return request({\n    url: \'${apiBase}\',\n    method: \'post\',\n    data\n  })\n}\n</#if>\n<#if genEditApi>export function update${className}(id, data) {\n  return request({\n    url: \'${apiBase}\',\n    method: \'put\',\n    data: { ...data, id }\n  })\n}\n</#if>\n<#if genDeleteApi>export function delete${className}(id) {\n  return request({\n    url: `${apiBase}/${\'$\'}{id}`,\n    method: \'delete\'\n  })\n}\n</#if>\n<#if hasFlow>// P3-3 审批流：四个动作走宿主统一的 /flow 接口，业务表只负责把 id 传过去\nexport function flowSubmit${className}(id, comment) {\n  return request({\n    url: \'/flow/submit\',\n    method: \'post\',\n    data: { flowCode: \'${flowCode}\', bizId: id, comment }\n  })\n}\n\nexport function flowApprove${className}(id, comment) {\n  return request({\n    url: \'/flow/approve\',\n    method: \'post\',\n    data: { flowCode: \'${flowCode}\', bizId: id, comment }\n  })\n}\n\nexport function flowReject${className}(id, comment) {\n  return request({\n    url: \'/flow/reject\',\n    method: \'post\',\n    data: { flowCode: \'${flowCode}\', bizId: id, comment }\n  })\n}\n\nexport function get${className}FlowRecords(id) {\n  return request({\n    url: \'/flow/records\',\n    method: \'get\',\n    params: { flowCode: \'${flowCode}\', bizId: id }\n  })\n}\n</#if>\n// <gen:end key=\"api-fns\">\n// ===== 以下为手写区：自定义请求写在这里，重新生成不会被覆盖 =====\n','src/api/${moduleName}.js',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:22',NULL,'2026-11-10 12:53:22'),(2120016941721612289,'vuePage','前端页面','frontend','<template>\n  <div class=\"app-container\">\n    <!-- <gen:begin key=\"vue-template\"> -->\n    <!-- 页头：一眼看清「我在哪个页面、这页能干什么」 -->\n    <div class=\"page-head\">\n      <div class=\"page-head__main\">\n        <h2 class=\"page-title\">${comment}</h2>\n        <p class=\"page-desc\">维护${comment}数据，可按条件筛选、编辑与导出</p>\n      </div>\n      <div class=\"page-head__meta\">\n        <span class=\"meta-pill\">{{ total }} 条记录</span>\n      </div>\n    </div>\n<#if vueQueryColumns?size gt 0>\n    <!-- 筛选区 -->\n    <el-card shadow=\"never\" class=\"filter-card\">\n      <el-form :inline=\"true\" :model=\"query\" @submit.native.prevent>\n<#list vueQueryColumns as c>\n        <el-form-item label=\"${c.commentLabel}\">\n<#if c.isSelect || c.isRadio>\n          <el-select v-model=\"query.${c.javaField}\" placeholder=\"请选择${c.commentLabel}\" clearable style=\"width: 160px\">\n            <el-option v-for=\"d in <#if c.hasDict>dicts.${c.dictType} || []<#elseif c.hasEnum>enumMap.${c.javaField} || []<#else>[]</#if>\" :key=\"d.value\" :label=\"d.label\" :value=\"d.value\" />\n          </el-select>\n<#elseif c.isSwitch>\n          <el-select v-model=\"query.${c.javaField}\" placeholder=\"请选择${c.commentLabel}\" clearable style=\"width: 120px\">\n            <el-option label=\"启用\" :value=\"1\" />\n            <el-option label=\"停用\" :value=\"0\" />\n          </el-select>\n<#elseif c.isNumberCtrl>\n          <el-input-number v-model=\"query.${c.javaField}\" controls-position=\"right\" style=\"width: 160px\" />\n<#elseif c.isDate>\n          <el-date-picker v-model=\"query.${c.javaField}\" type=\"date\" value-format=\"yyyy-MM-dd\" placeholder=\"请选择${c.commentLabel}\" style=\"width: 160px\" />\n<#elseif c.isDatetime>\n          <el-date-picker v-model=\"query.${c.javaField}\" type=\"datetime\" value-format=\"yyyy-MM-dd HH:mm:ss\" placeholder=\"请选择${c.commentLabel}\" style=\"width: 200px\" />\n<#else>\n          <el-input v-model=\"query.${c.javaField}\" placeholder=\"${c.commentLabel}\" clearable @keyup.enter.native=\"handleSearch\" />\n</#if>\n        </el-form-item>\n</#list>\n        <el-form-item>\n          <el-button v-hasPermi=\"[\'${permsPrefix}:query\']\" type=\"primary\" icon=\"el-icon-search\" @click=\"handleSearch\">查询</el-button>\n          <el-button icon=\"el-icon-refresh\" @click=\"handleReset\">重置</el-button>\n        </el-form-item>\n      </el-form>\n    </el-card>\n\n</#if>\n    <!-- 列表 -->\n    <el-card shadow=\"never\" class=\"table-card\">\n      <div slot=\"header\" class=\"card-header\">\n        <div class=\"card-title\">\n          <span class=\"title\">${comment}</span>\n          <span class=\"subtitle\">共 {{ total }} 条</span>\n        </div>\n        <div class=\"card-actions\">\n<#if genAddBtn>\n          <el-button v-hasPermi=\"[\'${permsPrefix}:add\']\" type=\"primary\" icon=\"el-icon-plus\" size=\"small\" @click=\"openDialog()\">新增${comment}</el-button>\n</#if>\n<#if hasExcelExport>\n          <el-button icon=\"el-icon-download\" size=\"small\" @click=\"handleExport\">导出</el-button>\n</#if>\n<#if hasExcelImport>\n          <el-button icon=\"el-icon-upload2\" size=\"small\" @click=\"importVisible = true\">导入</el-button>\n</#if>\n        </div>\n      </div>\n\n      <el-table\n        v-loading=\"loading\"\n        :data=\"list\"\n        class=\"data-table\"\n        stripe\n        header-cell-class-name=\"table-head-cell\"\n        empty-text=\"暂无数据\"\n<#if genTree>\n        row-key=\"id\"\n        :tree-props=\"{ children: \'children\', hasChildren: \'hasChildren\' }\"\n</#if>\n      >\n        <el-table-column prop=\"id\" label=\"ID\" width=\"<#if idColWidth gt 0>${idColWidth}<#else>70</#if>\" />\n<#list listColumns as c>\n<#if c.isMultiImage && fileEnabled>\n        <el-table-column prop=\"${c.javaField}\" label=\"${c.commentLabel}\" width=\"${c.colWidth}\" align=\"center\">\n          <template slot-scope=\"{ row }\">\n            <el-image v-if=\"firstImage(row.${c.javaField})\" :src=\"firstImage(row.${c.javaField})\" :preview-src-list=\"imageListOf(row.${c.javaField})\" fit=\"cover\" style=\"width: ${imageListSize}px; height: ${imageListSize}px; border-radius: 4px\">\n              <div slot=\"error\"><img src=\"/placeholder.svg\" alt=\"\" style=\"width: 100%; height: 100%; object-fit: cover\" /></div>\n            </el-image>\n            <span v-else>—</span>\n          </template>\n        </el-table-column>\n<#elseif c.isImage && fileEnabled>\n        <el-table-column prop=\"${c.javaField}\" label=\"${c.commentLabel}\" width=\"${c.colWidth}\" align=\"center\">\n          <template slot-scope=\"{ row }\">\n            <el-image v-if=\"row.${c.javaField}\" :src=\"row.${c.javaField}\" :preview-src-list=\"[row.${c.javaField}]\" fit=\"cover\" style=\"width: ${imageListSize}px; height: ${imageListSize}px; border-radius: 4px\">\n              <div slot=\"error\"><img src=\"/placeholder.svg\" alt=\"\" style=\"width: 100%; height: 100%; object-fit: cover\" /></div>\n            </el-image>\n            <span v-else>—</span>\n          </template>\n        </el-table-column>\n<#elseif c.isFile && fileEnabled>\n        <el-table-column prop=\"${c.javaField}\" label=\"${c.commentLabel}\" min-width=\"${c.colWidth}\" show-overflow-tooltip>\n          <template slot-scope=\"{ row }\">\n            <el-link v-if=\"row.${c.javaField}\" type=\"primary\" :href=\"row.${c.javaField}\" target=\"_blank\" icon=\"el-icon-document\">{{ row.${c.javaField}.split(\'/\').pop() }}</el-link>\n          </template>\n        </el-table-column>\n<#elseif c.hasRef>\n        <el-table-column prop=\"${c.javaField}\" label=\"${c.commentLabel}\" min-width=\"${c.colWidth}\" show-overflow-tooltip\n          :formatter=\"(row) => refText(\'${c.javaField}\', row.${c.javaField})\" />\n<#elseif c.isSwitch>\n        <el-table-column prop=\"${c.javaField}\" label=\"${c.commentLabel}\" width=\"${c.colWidth}\" align=\"center\">\n          <template slot-scope=\"{ row }\">\n            <el-tag :type=\"row.${c.javaField} === 1 ? \'success\' : \'info\'\" size=\"mini\">\n              {{ row.${c.javaField} === 1 ? \'启用\' : \'停用\' }}\n            </el-tag>\n          </template>\n        </el-table-column>\n<#elseif c.hasDict>\n        <el-table-column prop=\"${c.javaField}\" label=\"${c.commentLabel}\" min-width=\"${c.colWidth}\" show-overflow-tooltip\n          :formatter=\"(row) => dictText(\'${c.dictType}\', row.${c.javaField})\" />\n<#elseif c.hasEnum>\n        <el-table-column prop=\"${c.javaField}\" label=\"${c.commentLabel}\" min-width=\"${c.colWidth}\" show-overflow-tooltip\n          :formatter=\"(row) => enumText(\'${c.javaField}\', row.${c.javaField})\" />\n<#elseif c.isDatetime>\n        <el-table-column prop=\"${c.javaField}\" label=\"${c.commentLabel}\" width=\"${c.colWidth}\" align=\"center\" show-overflow-tooltip />\n<#elseif c.isDate>\n        <el-table-column prop=\"${c.javaField}\" label=\"${c.commentLabel}\" width=\"${c.colWidth}\" align=\"center\" />\n<#elseif c.isNumberCtrl || c.isNumber>\n        <el-table-column prop=\"${c.javaField}\" label=\"${c.commentLabel}\" width=\"${c.colWidth}\" align=\"right\" show-overflow-tooltip />\n<#elseif c.isText || c.isTextarea>\n        <el-table-column prop=\"${c.javaField}\" label=\"${c.commentLabel}\" min-width=\"${c.colWidth}\" show-overflow-tooltip />\n<#else>\n        <el-table-column prop=\"${c.javaField}\" label=\"${c.commentLabel}\" min-width=\"${c.colWidth}\" show-overflow-tooltip />\n</#if>\n</#list>\n        <el-table-column prop=\"updateTime\" label=\"更新时间\" width=\"170\" align=\"center\" />\n<#if genEditBtn || genDeleteBtn || hasDetail || hasFlow || genPrint>\n        <el-table-column label=\"操作\" width=\"${opColWidth}\" fixed=\"right\" align=\"center\">\n          <template slot-scope=\"{ row }\">\n<#if hasDetail>\n            <el-button type=\"text\" @click=\"openDetail(row)\">详情</el-button>\n</#if>\n<#if genPrint>\n            <el-button type=\"text\" @click=\"handlePrintRow(row)\">打印</el-button>\n</#if>\n<#if hasFlow>\n            <!--\n              审批按钮按单据状态出现，避免用户对着「已通过」的单子再点提交。\n              状态值约定：0 草稿 / 1 待审批 / 2 已通过 / 3 已驳回。\n              服务端还会按流程节点配的角色再校验一次，这里只做界面收敛。\n            -->\n            <el-button v-if=\"row.${flowStatusField} === \'0\' || row.${flowStatusField} === \'3\'\" type=\"text\" @click=\"handleFlow(\'submit\', row)\">提交</el-button>\n            <el-button v-if=\"row.${flowStatusField} === \'1\'\" type=\"text\" @click=\"handleFlow(\'approve\', row)\">审批</el-button>\n            <el-button v-if=\"row.${flowStatusField} === \'1\'\" type=\"text\" class=\"danger-btn\" @click=\"handleFlow(\'reject\', row)\">驳回</el-button>\n            <el-button type=\"text\" @click=\"openFlowRecords(row)\">流程</el-button>\n</#if>\n<#if hasPayStatus>\n            <!-- V6.3 支付接入约定：待支付的行给「去支付」入口，跳收银台并携带业务定位与金额（amount 列约定为分） -->\n            <el-button v-if=\"row.payStatus === 0 || row.payStatus === \'0\'\" type=\"text\" @click=\"goPay(row)\">去支付</el-button>\n</#if>\n<#if genEditBtn>\n            <el-button v-hasPermi=\"[\'${permsPrefix}:edit\']\" type=\"text\" @click=\"openDialog(row)\">编辑</el-button>\n</#if>\n<#if genDeleteBtn>\n            <el-button v-hasPermi=\"[\'${permsPrefix}:remove\']\" type=\"text\" class=\"danger-btn\" @click=\"handleDelete(row)\">删除</el-button>\n</#if>\n          </template>\n        </el-table-column>\n</#if>\n      </el-table>\n\n<#if genPageApi && !genTree>\n      <el-pagination\n        class=\"pagination\"\n        background\n        layout=\"total, sizes, prev, pager, next, jumper\"\n        :total=\"total\"\n        :page-sizes=\"[10, 20, 50]\"\n        :page-size=\"query.size\"\n        :current-page.sync=\"query.page\"\n        @size-change=\"handleSizeChange\"\n        @current-change=\"fetchList\"\n      />\n</#if>\n    </el-card>\n\n<#if hasDialog>\n<#assign twoColForm = (formColumns?size gt 6)>\n    <!-- 新增/编辑弹窗 -->\n    <el-dialog :title=\"form.id ? \'编辑${comment}\' : \'新增${comment}\'\" :visible.sync=\"dialogVisible\" width=\"<#if hasChild>900px<#elseif twoColForm>760px<#else>560px</#if>\" top=\"6vh\" class=\"form-dialog\">\n      <el-form ref=\"form\" :model=\"form\" :rules=\"rules\" label-width=\"<#if twoColForm>96px<#else>110px</#if>\">\n<#if twoColForm>\n        <el-row :gutter=\"20\">\n</#if>\n<#list formColumns as c>\n<#if twoColForm>\n          <el-col :span=\"12\">\n</#if>\n        <el-form-item<#if c.hasLink> v-if=\"link.visible(\'${c.javaField}\')\"</#if> label=\"${c.commentLabel}\" prop=\"${c.javaField}\">\n<#if c.isMultiImage && fileEnabled>\n          <multi-image-upload v-model=\"form.${c.javaField}\"<#if c.hasLink> :disabled=\"link.disabled(\'${c.javaField}\')\"</#if> />\n<#elseif c.isImage && fileEnabled>\n          <image-upload v-model=\"form.${c.javaField}\"<#if c.hasLink> :disabled=\"link.disabled(\'${c.javaField}\')\"</#if> />\n<#elseif c.isFile && fileEnabled>\n          <file-upload v-model=\"form.${c.javaField}\"<#if c.hasLink> :disabled=\"link.disabled(\'${c.javaField}\')\"</#if> />\n<#elseif c.hasRef>\n          <el-select v-model=\"form.${c.javaField}\"<#if c.hasLink> :disabled=\"link.disabled(\'${c.javaField}\')\"</#if> filterable remote clearable placeholder=\"输入关键字搜索${c.commentLabel}\"\n            :remote-method=\"kw => searchRef(\'${c.javaField}\', \'${c.refTable}\', \'${c.refLabel}\', kw)\"\n            :loading=\"refLoading[\'${c.javaField}\']\" style=\"width: 100%\">\n            <el-option v-for=\"o in refOptions[\'${c.javaField}\'] || []\" :key=\"o.id\" :label=\"o.label\" :value=\"o.id\" />\n          </el-select>\n<#elseif c.isSelect>\n          <el-select v-model=\"form.${c.javaField}\"<#if c.hasLink> :disabled=\"link.disabled(\'${c.javaField}\')\"</#if> placeholder=\"请选择${c.commentLabel}\" clearable style=\"width: 100%\">\n            <el-option v-for=\"d in <#if c.hasDict>dicts.${c.dictType} || []<#elseif c.hasEnum>enumMap.${c.javaField} || []<#else>[]</#if>\" :key=\"d.value\" :label=\"d.label\" :value=\"d.value\" />\n          </el-select>\n<#elseif c.isRadio>\n          <el-radio-group v-model=\"form.${c.javaField}\"<#if c.hasLink> :disabled=\"link.disabled(\'${c.javaField}\')\"</#if>>\n            <el-radio v-for=\"d in <#if c.hasDict>dicts.${c.dictType} || []<#elseif c.hasEnum>enumMap.${c.javaField} || []<#else>[]</#if>\" :key=\"d.value\" :label=\"d.value\">{{ d.label }}</el-radio>\n          </el-radio-group>\n<#elseif c.isSwitch>\n          <el-switch v-model=\"form.${c.javaField}\"<#if c.hasLink> :disabled=\"link.disabled(\'${c.javaField}\')\"</#if> :active-value=\"1\" :inactive-value=\"0\" />\n<#elseif c.isNumberCtrl>\n          <el-input-number v-model=\"form.${c.javaField}\"<#if c.hasLink> :disabled=\"link.disabled(\'${c.javaField}\')\"</#if> controls-position=\"right\" style=\"width: 100%\" />\n<#elseif c.isDate>\n          <el-date-picker v-model=\"form.${c.javaField}\"<#if c.hasLink> :disabled=\"link.disabled(\'${c.javaField}\')\"</#if> type=\"date\" value-format=\"yyyy-MM-dd\" placeholder=\"请选择${c.commentLabel}\" style=\"width: 100%\" />\n<#elseif c.isDatetime>\n          <el-date-picker v-model=\"form.${c.javaField}\"<#if c.hasLink> :disabled=\"link.disabled(\'${c.javaField}\')\"</#if> type=\"datetime\" value-format=\"yyyy-MM-dd HH:mm:ss\" placeholder=\"请选择${c.commentLabel}\" style=\"width: 100%\" />\n<#elseif c.isTextarea>\n          <el-input v-model=\"form.${c.javaField}\"<#if c.hasLink> :disabled=\"link.disabled(\'${c.javaField}\')\"</#if> type=\"textarea\" :rows=\"3\" placeholder=\"请输入${c.commentLabel}\" />\n<#else>\n          <el-input v-model=\"form.${c.javaField}\"<#if c.hasLink> :disabled=\"link.disabled(\'${c.javaField}\')\"</#if> placeholder=\"请输入${c.commentLabel}\" />\n</#if>\n        </el-form-item>\n<#if twoColForm>\n          </el-col>\n</#if>\n</#list>\n<#if twoColForm>\n        </el-row>\n</#if>\n<#if genTree>\n        <el-form-item label=\"上级节点\">\n          <el-cascader\n            v-model=\"form.${treeParentField}\"\n            :options=\"treeOptions\"\n            :props=\"{ value: \'id\', label: \'<#if treeLabelField?has_content>${treeLabelField}<#else>id</#if>\', children: \'children\', checkStrictly: true, emitPath: false }\"\n            clearable\n            placeholder=\"不选则为根节点\"\n            style=\"width: 100%\"\n          />\n        </el-form-item>\n</#if>\n      </el-form>\n\n<#if hasChild>\n      <el-tabs v-model=\"activeChildTab\" type=\"card\" class=\"child-tabs\">\n<#list children as child>\n        <el-tab-pane label=\"${child.comment}\" name=\"${child.varName}\">\n          <div class=\"child-bar\">\n            <el-button type=\"primary\" icon=\"el-icon-plus\" size=\"mini\" @click=\"addChildRow(\'${child.varName}\')\">添加明细</el-button>\n            <span class=\"child-tip\">主表与子表在同一事务中保存（先清后插）</span>\n          </div>\n          <el-table :data=\"${child.varName}Rows\" border size=\"mini\" class=\"child-table\">\n<#list child.formColumns as c>\n            <el-table-column label=\"${c.commentLabel}\" min-width=\"130\">\n              <template slot-scope=\"{ row }\">\n<#if c.isMultiImage && fileEnabled>\n                <multi-image-upload v-model=\"row.${c.javaField}\" />\n<#elseif c.isImage && fileEnabled>\n                <image-upload v-model=\"row.${c.javaField}\" width=\"${imageListSize}px\" height=\"${imageListSize}px\" />\n<#elseif c.isFile && fileEnabled>\n                <file-upload v-model=\"row.${c.javaField}\" />\n<#elseif c.isSwitch>\n                <el-switch v-model=\"row.${c.javaField}\" :active-value=\"1\" :inactive-value=\"0\" />\n<#elseif c.isNumberCtrl>\n                <el-input-number v-model=\"row.${c.javaField}\" controls-position=\"right\" size=\"mini\" style=\"width: 100%\" />\n<#elseif c.isDate>\n                <el-date-picker v-model=\"row.${c.javaField}\" type=\"date\" value-format=\"yyyy-MM-dd\" size=\"mini\" style=\"width: 100%\" />\n<#elseif c.isDatetime>\n                <el-date-picker v-model=\"row.${c.javaField}\" type=\"datetime\" value-format=\"yyyy-MM-dd HH:mm:ss\" size=\"mini\" style=\"width: 100%\" />\n<#else>\n                <el-input v-model=\"row.${c.javaField}\" size=\"mini\" placeholder=\"${c.commentLabel}\" />\n</#if>\n              </template>\n            </el-table-column>\n</#list>\n            <el-table-column label=\"操作\" width=\"<#if child.hasGrandChild>150<#else>70</#if>\" align=\"center\">\n              <template slot-scope=\"{ row, $index }\">\n<#list child.grandChildren as gc>\n                <el-button type=\"text\" @click=\"openGrandRows(\'${child.varName}\', \'${gc.varName}\', row)\">${gc.comment}</el-button>\n</#list>\n                <el-button type=\"text\" class=\"danger-btn\" @click=\"${child.varName}Rows.splice($index, 1)\">删除</el-button>\n              </template>\n            </el-table-column>\n          </el-table>\n<#if child.hasGrandChild>\n          <div class=\"child-tip\" style=\"margin-top: 6px\">\n            下级明细在点「确定」时与本级明细一起全量替换，弹窗里改完不必单独保存。\n          </div>\n</#if>\n        </el-tab-pane>\n</#list>\n      </el-tabs>\n</#if>\n\n      <div slot=\"footer\">\n        <el-button @click=\"dialogVisible = false\">取消</el-button>\n        <el-button type=\"primary\" :loading=\"submitting\" @click=\"submitForm\">确定</el-button>\n      </div>\n    </el-dialog>\n<#if hasGrandDialog>\n\n    <!-- 三级明细编辑：直接改选中行的下级数组（引用直改），保存时随主表一起提交 -->\n    <el-dialog\n      :title=\"grandTitle\"\n      :visible.sync=\"grandVisible\"\n      width=\"720px\"\n      append-to-body\n    >\n      <div class=\"child-bar\">\n        <el-button type=\"primary\" icon=\"el-icon-plus\" size=\"mini\" @click=\"addGrandRow\">添加{{ grandTitle }}</el-button>\n      </div>\n<#list children as child>\n<#list child.grandChildren as gc>\n      <el-table v-show=\"grandDialog === \'${child.varName}.${gc.varName}\'\" :data=\"grandRows\" border size=\"mini\" class=\"child-table\">\n<#list gc.formColumns as c>\n        <el-table-column label=\"${c.commentLabel}\" min-width=\"130\">\n          <template slot-scope=\"{ row }\">\n<#if c.isMultiImage && fileEnabled>\n            <multi-image-upload v-model=\"row.${c.javaField}\" />\n<#elseif c.isImage && fileEnabled>\n            <image-upload v-model=\"row.${c.javaField}\" width=\"${imageListSize}px\" height=\"${imageListSize}px\" />\n<#elseif c.isFile && fileEnabled>\n            <file-upload v-model=\"row.${c.javaField}\" />\n<#elseif c.isSwitch>\n            <el-switch v-model=\"row.${c.javaField}\" :active-value=\"1\" :inactive-value=\"0\" />\n<#elseif c.isNumberCtrl>\n            <el-input-number v-model=\"row.${c.javaField}\" controls-position=\"right\" size=\"mini\" style=\"width: 100%\" />\n<#elseif c.isDate>\n            <el-date-picker v-model=\"row.${c.javaField}\" type=\"date\" value-format=\"yyyy-MM-dd\" size=\"mini\" style=\"width: 100%\" />\n<#elseif c.isDatetime>\n            <el-date-picker v-model=\"row.${c.javaField}\" type=\"datetime\" value-format=\"yyyy-MM-dd HH:mm:ss\" size=\"mini\" style=\"width: 100%\" />\n<#else>\n            <el-input v-model=\"row.${c.javaField}\" size=\"mini\" placeholder=\"${c.commentLabel}\" />\n</#if>\n          </template>\n        </el-table-column>\n</#list>\n        <el-table-column label=\"操作\" width=\"70\" align=\"center\">\n          <template slot-scope=\"{ $index }\">\n            <el-button type=\"text\" class=\"danger-btn\" @click=\"grandRows.splice($index, 1)\">删除</el-button>\n          </template>\n        </el-table-column>\n      </el-table>\n</#list>\n</#list>\n      <div slot=\"footer\">\n        <el-button @click=\"grandVisible = false\">关闭</el-button>\n      </div>\n    </el-dialog>\n</#if>\n</#if>\n\n<#if hasDetail>\n    <!-- 详情抽屉（只读）。主子表：宽抽屉 + el-tabs，tab1 主表字段，tab2..N 每张明细一张只读表；\n         数据复用 /with-children 一次拉全，不逐 tab 发请求 -->\n    <el-drawer title=\"${comment}详情\" :visible.sync=\"detailVisible\" size=\"<#if hasChild>62%<#else>420px</#if>\">\n<#if hasChild>\n      <el-tabs v-model=\"activeDetailTab\" type=\"card\" class=\"detail-tabs\">\n        <el-tab-pane label=\"主表信息\" name=\"main\">\n          <div class=\"detail-body\">\n<#else>\n      <div class=\"detail-body\">\n</#if>\n<#if hasChild>            <div class=\"detail-row\">\n              <span class=\"detail-label\">ID</span>\n              <span class=\"detail-value\">{{ detail.id }}</span>\n            </div>\n<#else>\n        <div class=\"detail-row\">\n          <span class=\"detail-label\">ID</span>\n          <span class=\"detail-value\">{{ detail.id }}</span>\n        </div>\n</#if>\n<#list listColumns as c>\n<#if hasChild>          <div class=\"detail-row\">\n            <span class=\"detail-label\">${c.commentLabel}</span>\n<#else>        <div class=\"detail-row\">\n          <span class=\"detail-label\">${c.commentLabel}</span>\n</#if>\n<#if c.isMultiImage && fileEnabled>\n<#if hasChild>            <span class=\"detail-value\"><span v-if=\"imageListOf(detail.${c.javaField}).length\"><el-image v-for=\"(u, i) in imageListOf(detail.${c.javaField})\" :key=\"i\" :src=\"u\" :preview-src-list=\"imageListOf(detail.${c.javaField})\" fit=\"cover\" style=\"width: ${imageDetailSize}px; height: ${imageDetailSize}px; border-radius: 4px; margin-right: 6px\" /></span><span v-else>—</span></span>\n<#else>          <span class=\"detail-value\"><span v-if=\"imageListOf(detail.${c.javaField}).length\"><el-image v-for=\"(u, i) in imageListOf(detail.${c.javaField})\" :key=\"i\" :src=\"u\" :preview-src-list=\"imageListOf(detail.${c.javaField})\" fit=\"cover\" style=\"width: ${imageDetailSize}px; height: ${imageDetailSize}px; border-radius: 4px; margin-right: 6px\" /></span><span v-else>—</span></span>\n</#if>\n<#elseif c.isImage && fileEnabled>\n<#if hasChild>            <span class=\"detail-value\"><el-image v-if=\"detail.${c.javaField}\" :src=\"detail.${c.javaField}\" :preview-src-list=\"[detail.${c.javaField}]\" fit=\"cover\" style=\"width: ${imageDetailSize}px; height: ${imageDetailSize}px; border-radius: 4px\"><div slot=\"error\"><img src=\"/placeholder.svg\" alt=\"\" style=\"width: 100%; height: 100%; object-fit: cover\" /></div></el-image><span v-else>—</span></span>\n<#else>          <span class=\"detail-value\"><el-image v-if=\"detail.${c.javaField}\" :src=\"detail.${c.javaField}\" :preview-src-list=\"[detail.${c.javaField}]\" fit=\"cover\" style=\"width: ${imageDetailSize}px; height: ${imageDetailSize}px; border-radius: 4px\"><div slot=\"error\"><img src=\"/placeholder.svg\" alt=\"\" style=\"width: 100%; height: 100%; object-fit: cover\" /></div></el-image><span v-else>—</span></span>\n</#if>\n<#elseif c.isFile && fileEnabled>\n<#if hasChild>            <span class=\"detail-value\"><el-link v-if=\"detail.${c.javaField}\" type=\"primary\" :href=\"detail.${c.javaField}\" target=\"_blank\" icon=\"el-icon-document\">{{ detail.${c.javaField}.split(\'/\').pop() }}</el-link></span>\n<#else>          <span class=\"detail-value\"><el-link v-if=\"detail.${c.javaField}\" type=\"primary\" :href=\"detail.${c.javaField}\" target=\"_blank\" icon=\"el-icon-document\">{{ detail.${c.javaField}.split(\'/\').pop() }}</el-link></span>\n</#if>\n<#elseif c.hasRef>\n<#if hasChild>            <span class=\"detail-value\">{{ refText(\'${c.javaField}\', detail.${c.javaField}) }}</span>\n<#else>          <span class=\"detail-value\">{{ refText(\'${c.javaField}\', detail.${c.javaField}) }}</span>\n</#if>\n<#elseif c.isSwitch>\n<#if hasChild>            <span class=\"detail-value\">{{ detail.${c.javaField} === 1 ? \'启用\' : \'停用\' }}</span>\n<#else>          <span class=\"detail-value\">{{ detail.${c.javaField} === 1 ? \'启用\' : \'停用\' }}</span>\n</#if>\n<#elseif c.hasDict>\n<#if hasChild>            <span class=\"detail-value\">{{ dictText(\'${c.dictType}\', detail.${c.javaField}) }}</span>\n<#else>          <span class=\"detail-value\">{{ dictText(\'${c.dictType}\', detail.${c.javaField}) }}</span>\n</#if>\n<#elseif c.hasEnum>\n<#if hasChild>            <span class=\"detail-value\">{{ enumText(\'${c.javaField}\', detail.${c.javaField}) }}</span>\n<#else>          <span class=\"detail-value\">{{ enumText(\'${c.javaField}\', detail.${c.javaField}) }}</span>\n</#if>\n<#else>\n<#if hasChild>            <span class=\"detail-value\">{{ detail.${c.javaField} }}</span>\n<#else>          <span class=\"detail-value\">{{ detail.${c.javaField} }}</span>\n</#if>\n</#if>\n<#if hasChild>          </div>\n<#else>        </div>\n</#if>\n</#list>\n<#if hasChild>          <div class=\"detail-row\">\n            <span class=\"detail-label\">创建时间</span>\n            <span class=\"detail-value\">{{ detail.createTime }}</span>\n          </div>\n          <div class=\"detail-row\">\n            <span class=\"detail-label\">更新时间</span>\n            <span class=\"detail-value\">{{ detail.updateTime }}</span>\n          </div>\n          </div>\n        </el-tab-pane>\n<#list children as child>\n        <el-tab-pane label=\"${child.comment}\" name=\"${child.varName}\">\n          <el-table :data=\"detailGroupRows(\'${child.varName}\')\" border size=\"mini\" max-height=\"520\">\n<#list child.listColumns as c>\n            <el-table-column label=\"${c.commentLabel}\" min-width=\"120\" prop=\"${c.javaField}\">\n              <template slot-scope=\"{ row }\">\n<#if c.hasRef>\n                {{ refText(\'${c.javaField}\', row.${c.javaField}) }}\n<#elseif c.isSwitch>\n                {{ row.${c.javaField} === 1 ? \'启用\' : \'停用\' }}\n<#elseif c.hasDict>\n                {{ dictText(\'${c.dictType}\', row.${c.javaField}) }}\n<#elseif c.hasEnum>\n                {{ enumText(\'${c.javaField}\', row.${c.javaField}) }}\n<#else>\n                {{ row.${c.javaField} }}\n</#if>\n              </template>\n            </el-table-column>\n</#list>\n          </el-table>\n        </el-tab-pane>\n</#list>\n      </el-tabs>\n<#else>\n        <div class=\"detail-row\">\n          <span class=\"detail-label\">创建时间</span>\n          <span class=\"detail-value\">{{ detail.createTime }}</span>\n        </div>\n        <div class=\"detail-row\">\n          <span class=\"detail-label\">更新时间</span>\n          <span class=\"detail-value\">{{ detail.updateTime }}</span>\n        </div>\n      </div>\n</#if>\n    </el-drawer>\n</#if>\n\n<#if hasExcelImport>\n    <!-- 导入对话框 -->\n    <el-dialog title=\"导入${comment}\" :visible.sync=\"importVisible\" width=\"480px\">\n      <div class=\"import-tpl-tip\">\n        表头必须与模板一致。模板第 2 行是填写说明，\n        <b>填写真实数据前请先删掉说明行</b>。\n        <el-button type=\"text\" size=\"mini\" :loading=\"tplLoading\" @click=\"downloadTemplate\">下载模板</el-button>\n      </div>\n      <el-upload\n        drag\n        action=\"#\"\n        :auto-upload=\"false\"\n        :limit=\"1\"\n        :file-list=\"importFiles\"\n        :on-change=\"handleImportChange\"\n        accept=\".xlsx\"\n      >\n        <i class=\"el-icon-upload\" />\n        <div class=\"el-upload__text\">把 xlsx 拖到这里，或<em>点击选择</em></div>\n      </el-upload>\n      <div v-if=\"importResult\" class=\"import-result\">\n        <div class=\"import-summary\">\n          共 {{ importResult.total }} 行：成功 <b class=\"ok\">{{ importResult.success }}</b> 条，\n          跳过 <b>{{ importResult.skipped || 0 }}</b> 条（已存在），\n          失败 <b class=\"bad\">{{ importResult.failedCount || 0 }}</b> 条\n        </div>\n        <div v-if=\"importResult.failedCount\" class=\"import-fail-box\">\n          <div class=\"import-fail-head\">\n            <span>失败明细（显示前 20 条）</span>\n            <el-button type=\"text\" size=\"mini\" @click=\"downloadFailed\">下载全部明细</el-button>\n          </div>\n          <div v-for=\"(f, i) in importResult.failed.slice(0, 20)\" :key=\"i\" class=\"import-fail\">\n            第 {{ f.row }} 行：{{ f.msg }}\n          </div>\n          <div v-if=\"importResult.failedCount > 20\" class=\"import-fail-more\">\n            还有 {{ importResult.failedCount - 20 }} 条未显示，请下载明细查看\n          </div>\n        </div>\n      </div>\n      <div slot=\"footer\">\n        <el-button @click=\"importVisible = false\">关闭</el-button>\n        <el-button type=\"primary\" :loading=\"importing\" @click=\"submitImport\">开始导入</el-button>\n      </div>\n    </el-dialog>\n</#if>\n<#if hasFlow>\n    <!-- 提交/审批/驳回的确认框，顺便收一句意见 -->\n    <el-dialog\n      :title=\"flowAction === \'submit\' ? \'提交审批\' : (flowAction === \'reject\' ? \'驳回\' : \'审批通过\')\"\n      :visible.sync=\"flowDialogVisible\"\n      width=\"420px\"\n      append-to-body\n    >\n      <el-input\n        v-model=\"flowComment\"\n        type=\"textarea\"\n        :rows=\"3\"\n        maxlength=\"200\"\n        show-word-limit\n        :placeholder=\"flowAction === \'reject\' ? \'请填写驳回理由\' : \'审批意见（选填）\'\"\n      />\n      <div slot=\"footer\">\n        <el-button @click=\"flowDialogVisible = false\">取消</el-button>\n        <el-button type=\"primary\" :loading=\"flowSubmitting\" @click=\"submitFlow\">确定</el-button>\n      </div>\n    </el-dialog>\n    <!-- 审批记录抽屉：流程流水是只追加的，看的就是「谁在什么时候把单子推到了哪一步」 -->\n    <el-drawer title=\"${comment}审批记录\" :visible.sync=\"flowVisible\" size=\"480px\">\n      <div v-loading=\"flowLoading\" class=\"detail-body\">\n        <div v-if=\"!flowRecords.length\" class=\"flow-empty\">还没有流转记录</div>\n        <el-timeline v-else>\n          <el-timeline-item\n            v-for=\"(r, i) in flowRecords\"\n            :key=\"i\"\n            :timestamp=\"r.operTime\"\n            placement=\"top\"\n            :color=\"flowColor(r.action)\"\n          >\n            <div class=\"flow-node\">{{ flowActionText(r.action) }}　<span class=\"flow-status\">{{ flowStatusText(r.toStatus) }}</span></div>\n            <div class=\"flow-meta\">{{ r.operName || \'系统\' }}<span v-if=\"r.comment\">：{{ r.comment }}</span></div>\n          </el-timeline-item>\n        </el-timeline>\n      </div>\n    </el-drawer>\n</#if>\n    <!-- <gen:end key=\"vue-template\"> -->\n  </div>\n</template>\n\n<script>\nimport {\n<#if genPageApi>  get${className}List<#if genTree || genAddApi || genEditApi || genDeleteApi || hasChild || hasRef || hasExcelExport || hasExcelImport || hasFlow>,</#if>\n</#if>\n<#if genTree>  get${className}Tree<#if genAddApi || genEditApi || genDeleteApi || hasChild || hasRef || hasExcelExport || hasExcelImport || hasFlow>,</#if>\n</#if>\n<#if hasRef>  get${className}Options<#if genAddApi || genEditApi || genDeleteApi || hasChild || hasExcelExport || hasExcelImport || hasFlow>,</#if>\n</#if>\n<#if hasChild>  get${className}WithChildren,\n  save${className}WithChildren<#if genAddApi || genEditApi || genDeleteApi || hasExcelExport || hasExcelImport || hasFlow>,</#if>\n</#if>\n<#if hasExcelExport>  export${className}<#if genAddApi || genEditApi || genDeleteApi || hasExcelImport || hasFlow>,</#if>\n</#if>\n<#if hasExcelImport>  import${className}, download${className}Template<#if genAddApi || genEditApi || genDeleteApi || hasFlow>,</#if>\n</#if>\n<#if genAddApi>  create${className}<#if genEditApi || genDeleteApi>,</#if>\n</#if>\n<#if genEditApi>  update${className}<#if genDeleteApi>,</#if>\n</#if>\n<#if genDeleteApi>  delete${className}<#if hasFlow>,</#if>\n</#if>\n<#if hasFlow>\n  flowSubmit${className},\n  flowApprove${className},\n  flowReject${className},\n  get${className}FlowRecords,\n</#if>\n} from \'@/api/${moduleName}\'\n<#if vueHasDict || hasSingleUnique || hasExcelImport>\n// 字典兜底、唯一性查重、导入失败明细下载都直接用通用 request，不依赖宿主是否提供专用 api 模块\nimport request from \'@/utils/request\'\n</#if>\n<#if hasUpload>\n// V6.6 文件能力包：页面里有 image/file 列才引入上传组件（fileEnabled 网控在模型层，未开时列按文本框渲染）\nimport ImageUpload from \'@/components/ImageUpload.vue\'\nimport FileUpload from \'@/components/FileUpload.vue\'\n<#if hasMultiImage>\nimport MultiImageUpload from \'@/components/MultiImageUpload.vue\'\n</#if>\n</#if>\n\nconst defaultForm = () => ({\n  id: undefined,\n<#list formColumns as c>\n  ${c.javaField}: ${c.jsInit},\n</#list>\n<#if genTree>\n  ${treeParentField}: undefined,\n</#if>\n})\n<#if hasChild>\n// 每张子表的新行工厂：键 = 子表 varName（与后端 children[].key 一致）\nconst defaultChildMap = {\n<#list children as child>\n  \'${child.varName}\': () => ({<#list child.formColumns as c> ${c.javaField}: ${c.jsInit}<#if c_has_next>,</#if></#list> })<#if child_has_next>,</#if>\n</#list>\n}\n<#if hasGrandDialog>\n// 三级明细新行工厂：键 = \'子表.varName\'，与 grandDialog 状态对齐\nconst defaultGrandMap = {\n<#list children as child>\n<#list child.grandChildren as gc>\n  \'${child.varName}.${gc.varName}\': () => ({<#list gc.formColumns as c> ${c.javaField}: ${c.jsInit}<#if c_has_next>,</#if></#list> })<#if child_has_next || gc_has_next>,</#if>\n</#list>\n</#list>\n}\nconst grandTitleMap = {\n<#list children as child>\n<#list child.grandChildren as gc>\n  \'${child.varName}.${gc.varName}\': \'${gc.comment}\'<#if child_has_next || gc_has_next>,</#if>\n</#list>\n</#list>\n}\n</#if>\n</#if>\n\nexport default {\n  name: \'${className}\',\n<#if hasUpload>\n  components: { ImageUpload, FileUpload<#if hasMultiImage>, MultiImageUpload</#if> },\n</#if>\n  data() {\n    return {\n      // <gen:begin key=\"vue-data\">\n      loading: false,\n      list: [],\n      total: 0,\n      query: { page: 1, size: 10<#list vueQueryColumns as c>, ${c.javaField}: ${c.queryJsInit}</#list> },\n      dialogVisible: false,\n      submitting: false,\n<#if hasDetail>\n      detailVisible: false,\n      detail: {},\n<#if hasChild>\n      // V4.4 详情多 tab：children 组数组 [{key, comment, rows}]，与 /with-children 响应同构\n      detailChildren: [],\n      activeDetailTab: \'main\',\n</#if>\n</#if>\n<#if genTree>\n      treeOptions: [],\n</#if>\n<#if hasRef>\n      refOptions: {},\n      refLoading: {},\n</#if>\n<#if hasRefHelper>\n      // 列表/详情里把 xxxId 显示成名称用的字典：{ 字段名: { id: label } }\n      refLabels: {},\n</#if>\n<#if hasChild>\n      activeChildTab: \'${(children[0].varName)!\"\"}\',\n<#list children as child>\n      ${child.varName}Rows: [],\n</#list>\n<#if hasGrandDialog>\n      // 三级明细：grandRows 指向选中行的下级数组（直接改引用，弹窗里编辑等于改主结构），\n      // grandDialog 记录当前弹的是哪组（\'子表.varName\'），决定显示哪张编辑表\n      grandVisible: false,\n      grandRows: [],\n      grandTitle: \'\',\n      grandDialog: \'\',\n</#if>\n</#if>\n<#if hasExcelImport>\n      importVisible: false,\n      importing: false,\n      importFiles: [],\n      importResult: null,\n      tplLoading: false,\n</#if>\n<#if hasFlow>\n      flowVisible: false,\n      flowLoading: false,\n      flowRecords: [],\n      flowRow: null,\n      flowDialogVisible: false,\n      flowAction: \'\',\n      flowComment: \'\',\n      flowSubmitting: false,\n</#if>\n<#if vueHasDict>\n      dicts: {<#list dictCodes as code> ${code}: []<#if code_has_next>,</#if></#list> },\n</#if>\n<#if vueHasEnum>\n      // 注释枚举内联在页面里：不依赖后端字典接口，页面秒开即可回显\n      enumMap: {\n<#list enumColumns as c>        ${c.javaField}: ${c.enumJs}<#if c_has_next>,</#if>\n</#list>      },\n</#if>\n      rules: {<#list formColumns as c><#if c.hasVueRule>\n        ${c.javaField}: ${c.vueRule},</#if></#list>\n<#if hasSingleUnique>\n        // P1-3 唯一性校验：失焦时异步查重，后端同样有兜底校验\n<#list uniqueColumns as c>\n        ${c.javaField}: [\n          { required: ${c.isRequired?c}, message: \'${c.commentLabel}不能为空\', trigger: \'blur\' },\n          { validator: this.uniqueValidator(\'${c.javaField}\'), trigger: \'blur\' }\n        ],</#list>\n</#if>\n      },\n      form: defaultForm()<#if hasLink>,\n      // P1-4 表单联动：由字段配置的 linkRule 驱动，visible/disabled/required 三类规则\n      linkRules: [<#list formColumns as c><#if c.hasLink>{ field: \'${c.javaField}\', label: \'${c.commentLabel}\', rule: ${c.linkRule} }<#if c_has_next>,</#if></#if></#list>]<#if hasLink>,\n      linkState: {}</#if></#if>\n      // <gen:end key=\"vue-data\">\n    }\n  },\n  created() {\n<#if vueHasDict>\n    this.loadDicts()\n</#if>\n<#if hasRef>\n    this.loadRefLabels()\n</#if>\n    this.fetchList()\n  },\n<#if hasLink>\n  computed: {\n    /**\n     * P1-4 表单联动求值器。模板里用 link.visible(field) / link.disabled(field) 取状态，\n     * 规则统一从 linkRules 读取，生成物里不写死任何业务字段名。\n     * 规则格式：[{ field, label, rule: { when, op, value, effect, else } }]\n     *   when  触发源字段（可与 field 相同）\n     *   op    eq / ne / in / notIn / notEmpty / empty\n     *   value 比对值（in / notIn 用数组）\n     *   effect 满足条件时的效果：show / hide / enable / disable / required / optional\n     *   else   不满足条件时的效果（缺省按 effect 的反义）\n     */\n    link() {\n      const hit = field => this.linkState[field] || {}\n      return {\n        // 没配联动规则的字段恒显示、恒可用，行为与未启用该特性时完全一致\n        visible: field => (this.hasLinkRule(field) ? hit(field).visible !== false : true),\n        disabled: field => hit(field).disabled === true,\n        required: field => hit(field).required === true\n      }\n    }\n  },\n  watch: {\n    // P1-4 联动触发源变化时刷新状态；deep 保证对象/数组字段变化也能捕获\n    form: {\n      deep: true,\n      handler() {\n        this.applyLink()\n      }\n    }\n  },\n</#if>\n  methods: {\n    // <gen:begin key=\"vue-methods\">\n<#if hasLink>\n    /**\n     * P1-4 表单联动：按 linkRules 重新计算每个字段的 显隐/禁用/必填 状态。\n     * 表单变化时由 watch(form) 触发，打开弹窗时由 openDialog 主动调用一次。\n     */\n    applyLink() {\n      const next = {}\n      this.linkRules.forEach(item => {\n        const rule = item.rule || {}\n        const source = rule.when || item.field\n        next[item.field] = this.evalLink(rule, this.form[source])\n      })\n      Object.keys(next).forEach(field => {\n        const state = next[field]\n        this.$set(this.linkState, field, state)\n        // 必填状态同步进校验规则；隐藏字段不参与校验，避免提交时被看不见的字段拦下\n        if (!state.visible) {\n          this.$set(this.rules, field, [])\n        } else if (state.required) {\n          this.$set(this.rules, field, [{ required: true, message: this.linkLabel(field) + \'不能为空\', trigger: \'blur\' }])\n        } else if (this.rules[field] && this.rules[field].some(r => r.required)) {\n          this.$set(this.rules, field, [])\n        }\n      })\n    },\n    /**\n     * 单个规则求值。\n     * rule = { when, op, value, effect, else }\n     *   when   触发源字段，缺省为字段自身\n     *   op     eq / ne / in / notIn / notEmpty / empty\n     *   value  eq/ne 用标量，in/notIn 用数组\n     *   effect 条件成立时的效果：show/hide/enable/disable/required/optional\n     *   else   条件不成立时的效果，缺省取 effect 的反义\n     */\n    evalLink(rule, value) {\n      const op = rule.op || \'eq\'\n      const expect = rule.value\n      const isBlank = v => v === \'\' || v === null || v === undefined\n        || (Array.isArray(v) && v.length === 0)\n      const same = v => String(v) === String(value)\n      let matched = true\n      if (op === \'eq\') matched = same(expect)\n      else if (op === \'ne\') matched = !same(expect)\n      else if (op === \'in\') matched = (expect || []).some(same)\n      else if (op === \'notIn\') matched = !(expect || []).some(same)\n      else if (op === \'notEmpty\') matched = !isBlank(value)\n      else if (op === \'empty\') matched = isBlank(value)\n\n      const state = { visible: true, disabled: false, required: false }\n      const apply = effect => {\n        if (effect === \'show\') state.visible = true\n        else if (effect === \'hide\') state.visible = false\n        else if (effect === \'enable\') state.disabled = false\n        else if (effect === \'disable\') state.disabled = true\n        else if (effect === \'required\') state.required = true\n        else if (effect === \'optional\') state.required = false\n      }\n      const inverse = {\n        show: \'hide\', hide: \'show\',\n        enable: \'disable\', disable: \'enable\',\n        required: \'optional\', optional: \'required\'\n      }\n      const hitEffect = rule.effect || \'show\'\n      apply(matched ? hitEffect : (rule.else || inverse[hitEffect] || \'hide\'))\n      return state\n    },\n    hasLinkRule(field) {\n      return this.linkRules.some(item => item.field === field)\n    },\n    linkLabel(field) {\n      const hit = this.linkRules.find(item => item.field === field)\n      return hit ? hit.label : field\n    },\n</#if>\n<#if hasSingleUnique>\n    /**\n     * P1-3 唯一性异步校验：字段失焦时查重。\n     * 编辑场景要排除自身 id，否则「不改这个字段直接保存」会被自己挡住。\n     */\n    uniqueValidator(field) {\n      return (rule, value, callback) => {\n        if (value === \'\' || value === null || value === undefined) {\n          callback()\n          return\n        }\n        request({\n          url: \'/${tableName}/check-unique\',\n          method: \'get\',\n          params: { field, value, excludeId: this.form.id || undefined }\n        }).then(res => {\n          if (res.data === true) {\n            callback(new Error(this.columnLabel(field) + \'已存在\'))\n          } else {\n            callback()\n          }\n        }).catch(() => {\n          // 查重接口不可用时不阻断用户提交，后端保存时仍有兜底校验\n          callback()\n        })\n      }\n    },\n    columnLabel(field) {\n      const map = {<#list uniqueColumns as c> ${c.javaField}: \'${c.commentLabel}\'<#if c_has_next>,</#if></#list> }\n      return map[field] || field\n    },\n</#if>\n<#if hasMultiImage>\n    // V6.8 多图字段：库里存 URL JSON 数组字符串。解析失败一律降级为空数组，\n    // 不让一条脏数据把整页渲染打挂（列表/详情/详情预览三处共用这两个方法）。\n    imageListOf(raw) {\n      if (!raw) return []\n      if (Array.isArray(raw)) return raw.filter(Boolean)\n      try {\n        const arr = JSON.parse(raw)\n        return Array.isArray(arr) ? arr.filter(Boolean) : []\n      } catch (e) {\n        return []\n      }\n    },\n    firstImage(raw) {\n      const list = this.imageListOf(raw)\n      return list.length ? list[0] : \'\'\n    },\n</#if>\n<#if vueHasDict>\n    async loadDicts() {\n      const codes = [<#list dictCodes as code>\'${code}\'<#if code_has_next>, </#if></#list>]\n      await Promise.all(codes.map(async code => {\n        try {\n          // 直接走通用 request，不依赖宿主工程是否提供 @/api/dict；\n          // 宿主没有字典接口时这里会抛错，下面 catch 把选项降级为空数组，页面照常可用\n          const res = await request({ url: \'${apiRoot}/system/dict/data/type/\' + code, method: \'get\' })\n          this.$set(this.dicts, code, (res && res.data) || [])\n        } catch (e) {\n          this.$set(this.dicts, code, [])\n        }\n      }))\n    },\n    dictText(code, value) {\n      const hit = (this.dicts[code] || []).find(d => String(d.value) === String(value))\n      return hit ? hit.label : (value === undefined || value === null ? \'\' : value)\n    },\n</#if>\n<#if vueHasEnum>\n    // 枚举翻译：值可能是数字也可能是字符串，统一按字符串比，避免 1 与 \'1\' 对不上\n    enumText(field, value) {\n      const hit = (this.enumMap[field] || []).find(d => String(d.value) === String(value))\n      return hit ? hit.label : (value === undefined || value === null || value === \'\' ? \'\' : value)\n    },\n</#if>\n<#if genTree>\n    async fetchList() {\n      this.loading = true\n      try {\n        const res = await get${className}Tree()\n        this.list = res.data || []\n        this.treeOptions = res.data || []\n        this.total = this.list.length\n      } catch (e) {\n        this.list = []\n        this.total = 0\n      } finally {\n        this.loading = false\n      }\n    },\n    handleSearch() {\n      this.fetchList()\n    },\n    handleReset() {\n      this.query = { page: 1, size: this.query.size<#list vueQueryColumns as c>, ${c.javaField}: ${c.jsInit}</#list> }\n      this.fetchList()\n    },\n    handleSizeChange(size) {\n      this.query.size = size\n      this.fetchList()\n    },\n<#elseif genPageApi>\n    async fetchList() {\n      this.loading = true\n      try {\n        const res = await get${className}List(this.query)\n        this.list = res.data.list || []\n        this.total = res.data.total || 0\n      } catch (e) {\n        this.list = []\n        this.total = 0\n      } finally {\n        this.loading = false\n      }\n    },\n    handleSearch() {\n      this.query.page = 1\n      this.fetchList()\n    },\n    handleReset() {\n      this.query = { page: 1, size: this.query.size<#list vueQueryColumns as c>, ${c.javaField}: ${c.jsInit}</#list> }\n      this.fetchList()\n    },\n    handleSizeChange(size) {\n      this.query.size = size\n      this.query.page = 1\n      this.fetchList()\n    },\n<#else>\n    async fetchList() {},\n</#if>\n<#if hasRef>\n    async searchRef(field, refTable, label, keyword) {\n      this.$set(this.refLoading, field, true)\n      try {\n        const res = await get${className}Options(refTable, label, keyword)\n        this.$set(this.refOptions, field, res.data || [])\n      } catch (e) {\n        this.$set(this.refOptions, field, [])\n      } finally {\n        this.$set(this.refLoading, field, false)\n      }\n    },\n    initRefs() {\n<#list refColumns as c>\n      this.searchRef(\'${c.javaField}\', \'${c.refTable}\', \'${c.refLabel}\', \'\')\n</#list>\n    },\n    /**\n     * 列表里的 xxxId 显示成名称。\n     * 关联表通常是字典/客户/产品这类小表，一次性拉成 { id: 名称 } 比逐行查省得多；\n     * 拉不到就退回显示原始 ID，页面不会因为关联表没权限/没数据而白屏。\n     */\n    loadRefLabels() {\n<#list refColumns as c>\n      this.fetchRefLabels(\'${c.javaField}\', \'${c.refTable}\', \'${c.refLabel}\')\n</#list>\n    },\n    async fetchRefLabels(field, refTable, label) {\n      try {\n        const res = await get${className}Options(refTable, label, \'\')\n        const map = {}\n        ;(res.data || []).forEach(o => { map[String(o.id)] = o.label })\n        this.$set(this.refLabels, field, map)\n      } catch (e) {\n        this.$set(this.refLabels, field, {})\n      }\n    },\n</#if>\n<#if hasRefHelper>\n    /**\n     * 把 xxxId 显示成名称：主表列与子表明细列都会用到，定义跟随 hasRefHelper\n     * （主表无引用列但子表外键有引用时也必须存在，否则明细行渲染崩溃）。\n     */\n    refText(field, id) {\n      if (id === null || id === undefined || id === \'\') {\n        return \'\'\n      }\n      const map = this.refLabels[field]\n      return (map && map[String(id)]) || id\n    },\n</#if>\n<#if hasDetail>\n    openDetail(row) {\n      this.detail = row || {}\n      this.detailVisible = true\n<#if hasChild>\n      this.activeDetailTab = \'main\'\n      this.loadDetailChildren(row && row.id)\n</#if>\n    },\n</#if>\n<#if hasDetail && hasChild>\n    /**\n     * 详情抽屉的明细数据：复用 /with-children 一次拉全，不逐 tab 发请求\n     */\n    async loadDetailChildren(id) {\n      this.detailChildren = []\n      if (!id) return\n      try {\n        const res = await get${className}WithChildren(id)\n        this.detailChildren = (res.data && res.data.children) || []\n      } catch (e) {\n        /* 拦截器已提示；明细保持为空 */\n      }\n    },\n    detailGroupRows(key) {\n      const group = this.detailChildren.find(g => g.key === key)\n      return (group && group.rows) || []\n    },\n</#if>\n<#if hasDialog>\n    openDialog(row) {\n      this.form = row ? { ...defaultForm(), ...row } : defaultForm()\n<#if hasChild>\n<#list children as child>\n      this.${child.varName}Rows = []\n</#list>\n</#if>\n      this.dialogVisible = true\n<#if hasRef>\n      this.initRefs()\n</#if>\n<#if hasChild>\n      if (row && row.id) {\n        this.loadChildren(row.id)\n      }\n</#if>\n      this.$nextTick(() => {\n<#if hasLink>\n        this.applyLink()\n</#if>\n        if (this.$refs.form) this.$refs.form.clearValidate()\n      })\n    },\n<#if hasChild>\n    async loadChildren(id) {\n<#list children as child>\n      this.${child.varName}Rows = []\n</#list>\n      try {\n        const res = await get${className}WithChildren(id)\n        // 后端 children: [{key, tableName, comment, rows}]；key 即子表 varName\n        const groups = (res.data && res.data.children) || []\n        groups.forEach(g => {\n          if (this[g.key + \'Rows\'] !== undefined) {\n            this[g.key + \'Rows\'] = g.rows || []\n          }\n        })\n      } catch (e) {\n        /* 拦截器已提示；保持空明细 */\n      }\n    },\n    addChildRow(tab) {\n      const factory = defaultChildMap[tab]\n      this[tab + \'Rows\'].push(factory ? factory() : {})\n    },\n<#if hasGrandDialog>\n    /**\n     * 打开某一行的下级明细。用 $set 保障数组存在，\n     * 因为后端返回的 VO 里该字段可能为 null（没有下级时）。\n     */\n    openGrandRows(childVar, gcVar, row) {\n      const field = gcVar + \'s\'\n      if (!row[field]) {\n        this.$set(row, field, [])\n      }\n      this.grandRows = row[field]\n      this.grandDialog = childVar + \'.\' + gcVar\n      this.grandTitle = grandTitleMap[this.grandDialog] || \'下级明细\'\n      this.grandVisible = true\n    },\n    addGrandRow() {\n      const factory = defaultGrandMap[this.grandDialog]\n      this.grandRows.push(factory ? factory() : {})\n    },\n</#if>\n</#if>\n<#if genPrint>\n    /**\n     * 打印单据：跳转独立打印页（无后台导航壳，window.print 直出 A4）\n     */\n    handlePrintRow(row) {\n      this.$router.push(\'/print/${moduleName}/\' + row.id)\n    },\n</#if>\n<#if hasPayStatus>\n    /**\n     * V6.3 去支付：跳收银台，携带业务定位（businessType/businessId）、标题与金额。\n     * 金额约定取 amount 列（单位分）；表里没有 amount 列时收银台手动输入。\n     */\n    goPay(row) {\n      this.$router.push({ path: \'/pay/cashier\', query: {\n        subject: \'${comment} \' + row.id,\n        amount: row.amount !== undefined && row.amount !== null ? (row.amount / 100).toFixed(2) : \'\',\n        businessType: \'${tableName}\',\n        businessId: row.id,\n        redirect: this.$route.fullPath\n      } })\n    },\n</#if>\n    async submitForm() {\n      const valid = await this.$refs.form.validate().catch(() => false)\n      if (!valid) return\n      this.submitting = true\n      try {\n<#if hasChild>\n        // 子表按组提交：与后端约定 null=不动该子表、[]=清空；编辑页全部组都提交（全量替换）\n        const payload = { master: this.form }\n<#list children as child>\n        payload.${child.varName}Rows = this.${child.varName}Rows\n</#list>\n        await save${className}WithChildren(payload)\n        this.$message.success(this.form.id ? \'更新成功\' : \'创建成功\')\n<#else>\n        if (this.form.id) {\n          await update${className}(this.form.id, this.form)\n        } else {\n          await create${className}(this.form)\n        }\n        this.$message.success(this.form.id ? \'更新成功\' : \'创建成功\')\n</#if>\n        this.dialogVisible = false\n        this.fetchList()\n      } catch (e) { /* 拦截器已提示 */ } finally {\n        this.submitting = false\n      }\n    },\n</#if>\n<#if genDeleteBtn>\n    handleDelete(row) {\n      this.$confirm(`确定删除该${comment}吗？`, \'提示\', { type: \'warning\' })\n        .then(async () => {\n          await delete${className}(row.id)\n          this.$message.success(\'删除成功\')\n          if (this.list.length === 1 && this.query.page > 1) this.query.page--\n          this.fetchList()\n        })\n        .catch(() => {})\n    }<#if hasExcelExport || hasExcelImport || hasFlow>,</#if>\n</#if>\n<#if hasExcelExport>\n    async handleExport() {\n      try {\n        const res = await export${className}(this.query)\n        const blob = new Blob([res.data], { type: \'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\' })\n        const url = window.URL.createObjectURL(blob)\n        const a = document.createElement(\'a\')\n        a.href = url\n        a.download = \'${comment}.xlsx\'\n        a.click()\n        window.URL.revokeObjectURL(url)\n      } catch (e) { /* 拦截器已提示 */ }\n    }<#if hasExcelImport || hasFlow>,</#if>\n</#if>\n<#if hasExcelImport>\n    handleImportChange(file, fileList) {\n      this.importFiles = fileList.slice(-1)\n      this.importResult = null\n    },\n    /**\n     * P2-4 下载空白模板：表头与后端 /import 的表头匹配逻辑同源生成，\n     * 用户拿到的模板一定能导回去。\n     */\n    async downloadTemplate() {\n      this.tplLoading = true\n      try {\n        const res = await download${className}Template()\n        const blob = new Blob([res.data], { type: \'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\' })\n        const url = window.URL.createObjectURL(blob)\n        const a = document.createElement(\'a\')\n        a.href = url\n        a.download = \'${comment}导入模板.xlsx\'\n        a.click()\n        window.URL.revokeObjectURL(url)\n      } catch (e) { /* 拦截器已提示 */ } finally {\n        this.tplLoading = false\n      }\n    },\n    async submitImport() {\n      if (!this.importFiles.length) {\n        this.$message.warning(\'请先选择文件\')\n        return\n      }\n      this.importing = true\n      try {\n        const res = await import${className}(this.importFiles[0].raw)\n        this.importResult = res.data || { total: 0, success: 0, skipped: 0, failedCount: 0, failed: [] }\n        const summary = \'导入完成：成功 \' + this.importResult.success + \' 条\'\n          + (this.importResult.skipped ? \'，跳过 \' + this.importResult.skipped + \' 条\' : \'\')\n          + (this.importResult.failedCount ? \'，失败 \' + this.importResult.failedCount + \' 条\' : \'\')\n        if (this.importResult.failedCount) {\n          this.$message.warning(summary)\n        } else {\n          this.$message.success(summary)\n        }\n        this.fetchList()\n      } catch (e) { /* 拦截器已提示 */ } finally {\n        this.importing = false\n      }\n    },\n    /**\n     * P1-5 失败明细下载：把「行号|原因」传给后端生成 xlsx，\n     * 前端只负责触发浏览器下载，不在页面里堆几百行错误。\n     */\n    async downloadFailed() {\n      const list = (this.importResult && this.importResult.failed) || []\n      if (!list.length) {\n        this.$message.warning(\'没有失败记录\')\n        return\n      }\n      try {\n        const res = await request({\n          url: \'/${tableName}/import/failed\',\n          method: \'get\',\n          params: { msg: list.map(f => f.row + \'|\' + f.msg) },\n          responseType: \'blob\'\n        })\n        const blob = new Blob([res.data], { type: \'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\' })\n        const url = window.URL.createObjectURL(blob)\n        const a = document.createElement(\'a\')\n        a.href = url\n        a.download = \'${comment}导入失败明细.xlsx\'\n        a.click()\n        window.URL.revokeObjectURL(url)\n      } catch (e) { /* 拦截器已提示 */ }\n    }<#if hasFlow>,</#if>\n</#if>\n<#if hasFlow>\n    /**\n     * 提交 / 审批 / 驳回共用一条通道，避免三份几乎一样的代码。\n     * 审批意见走一个小弹窗，不逼用户在列表里用 prompt —— prompt 没法做多行和必填校验。\n     */\n    handleFlow(action, row) {\n      this.flowAction = action\n      this.flowRow = row\n      this.flowComment = \'\'\n      this.flowDialogVisible = true\n    },\n    async submitFlow() {\n      if (!this.flowRow) return\n      const map = {\n        submit: { fn: flowSubmit${className}, text: \'提交\' },\n        approve: { fn: flowApprove${className}, text: \'审批通过\' },\n        reject: { fn: flowReject${className}, text: \'驳回\' }\n      }\n      const act = map[this.flowAction]\n      if (!act) return\n      this.flowSubmitting = true\n      try {\n        await act.fn(this.flowRow.id, this.flowComment)\n        this.$message.success(act.text + \'成功\')\n        this.flowDialogVisible = false\n        this.fetchList()\n      } catch (e) { /* 拦截器已提示 */ } finally {\n        this.flowSubmitting = false\n      }\n    },\n    async openFlowRecords(row) {\n      this.flowRow = row\n      this.flowRecords = []\n      this.flowVisible = true\n      this.flowLoading = true\n      try {\n        const res = await get${className}FlowRecords(row.id)\n        this.flowRecords = res.data || []\n      } catch (e) { /* 拦截器已提示 */ } finally {\n        this.flowLoading = false\n      }\n    },\n    /** 动作枚举转中文，后端只存 SUBMIT / APPROVE / REJECT */\n    flowActionText(action) {\n      return ({ SUBMIT: \'提交\', APPROVE: \'审批通过\', REJECT: \'驳回\' })[action] || action\n    },\n    flowStatusText(status) {\n      return ({ \'0\': \'草稿\', \'1\': \'待审批\', \'2\': \'已通过\', \'3\': \'已驳回\' })[status] || status\n    },\n    flowColor(action) {\n      return ({ SUBMIT: \'#909399\', APPROVE: \'#67c23a\', REJECT: \'#f56c6c\' })[action] || \'#c0c4cc\'\n    }\n</#if>\n    // <gen:end key=\"vue-methods\">\n    // ===== 以下为手写区：自定义方法写在这里，重新生成不会被覆盖 =====\n  }\n}\n</script>\n\n<style scoped>\n/* <gen:begin key=\"vue-style\"> */\n.app-container {\n  padding: 0;\n  background: transparent;\n}\n\n/* ===== 页头 ===== */\n.page-head {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 16px;\n  margin-bottom: 16px;\n}\n\n.page-title {\n  margin: 0;\n  font-size: 20px;\n  font-weight: 600;\n  color: #111827;\n  letter-spacing: 0.2px;\n}\n\n.page-desc {\n  margin: 6px 0 0;\n  font-size: 12px;\n  color: #8a94a6;\n}\n\n.page-head__meta {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding-top: 4px;\n}\n\n.meta-pill {\n  padding: 4px 12px;\n  border-radius: 20px;\n  background: #eef2ff;\n  color: #4d7cfe;\n  font-size: 12px;\n  font-weight: 500;\n}\n\n/* ===== 卡片 ===== */\n.filter-card,\n.table-card {\n  border: none;\n  border-radius: 12px;\n  box-shadow: 0 1px 2px rgba(16, 24, 40, 0.04), 0 6px 20px rgba(16, 24, 40, 0.05);\n}\n\n.filter-card {\n  margin-bottom: 16px;\n}\n\n.filter-card >>> .el-card__body {\n  padding: 18px 18px 4px;\n}\n\n.filter-card >>> .el-form-item {\n  margin-right: 16px;\n  margin-bottom: 14px;\n}\n\n.filter-card >>> .el-form-item__label {\n  color: #5a6478;\n  font-size: 13px;\n}\n\n.table-card >>> .el-card__header {\n  padding: 16px 18px;\n  border-bottom: 1px solid #eef1f7;\n}\n\n.card-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.card-title {\n  display: flex;\n  align-items: baseline;\n}\n\n.card-title .title {\n  font-size: 15px;\n  font-weight: 600;\n  color: #111827;\n}\n\n.card-title .subtitle {\n  margin-left: 10px;\n  font-size: 12px;\n  color: #909399;\n}\n\n.card-actions >>> .el-button + .el-button {\n  margin-left: 8px;\n}\n\n/* ===== 表格 ===== */\n.data-table >>> .table-head-cell {\n  background: #f7f9fc !important;\n  color: #5c6270;\n  font-weight: 600;\n}\n\n.data-table >>> td {\n  padding: 11px 0;\n}\n\n.data-table >>> .el-table__row:hover > td {\n  background: #f5f9ff;\n}\n\n.data-table >>> .el-button--text {\n  padding: 4px 6px;\n}\n\n/* ===== 分页 ===== */\n.pagination {\n  margin-top: 18px;\n  text-align: right;\n}\n\n.danger-btn {\n  color: #f56c6c;\n}\n\n.child-bar {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  margin-bottom: 8px;\n}\n\n.child-tip {\n  color: #909399;\n  font-size: 12px;\n}\n\n.import-summary {\n  margin-bottom: 8px;\n}\n\n.import-tpl-tip {\n  margin-bottom: 10px;\n  padding: 8px 12px;\n  background: #f5f7fa;\n  border-radius: 4px;\n  font-size: 12px;\n  line-height: 1.7;\n  color: #606266;\n}\n\n.import-summary .ok {\n  color: #67c23a;\n}\n\n.import-summary .bad {\n  color: #f56c6c;\n}\n\n.import-fail-box {\n  max-height: 200px;\n  overflow: auto;\n  padding: 8px;\n  background: #fdf6ec;\n  border-radius: 4px;\n}\n\n.import-fail-head {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 4px;\n  font-weight: 600;\n}\n\n.import-fail {\n  color: #f56c6c;\n  font-size: 12px;\n  line-height: 20px;\n}\n\n.import-fail-more {\n  color: #909399;\n  font-size: 12px;\n}\n\n.child-table {\n  margin-bottom: 8px;\n}\n\n.detail-body {\n  padding: 0 20px;\n}\n\n.detail-row {\n  display: flex;\n  padding: 8px 0;\n  border-bottom: 1px solid #ebeef5;\n  font-size: 13px;\n}\n\n.detail-label {\n  width: 110px;\n  color: #909399;\n  flex-shrink: 0;\n}\n\n.detail-value {\n  color: #303133;\n  word-break: break-all;\n}\n\n.import-result {\n  margin-top: 12px;\n  font-size: 13px;\n}\n\n.import-fail {\n  color: #f56c6c;\n}\n<#if hasFlow>\n\n.flow-empty {\n  padding: 40px 0;\n  text-align: center;\n  color: #909399;\n  font-size: 13px;\n}\n\n.flow-node {\n  font-size: 14px;\n  color: #303133;\n}\n\n.flow-status {\n  font-size: 12px;\n  color: #909399;\n}\n\n.flow-meta {\n  margin-top: 4px;\n  font-size: 13px;\n  color: #606266;\n  word-break: break-all;\n}\n</#if>\n</style>\n/* <gen:end key=\"vue-style\"> */\n','src/views/${moduleName}/index.vue',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:22',NULL,'2026-11-10 12:53:22'),(2120016941914550274,'printPage','打印单据页','frontend','<template>\n  <div class=\"print-wrap\" v-loading=\"loading\">\n    <!-- 屏幕工具条：打印时整体隐藏 -->\n    <div class=\"print-toolbar no-print\">\n      <el-button type=\"primary\" icon=\"el-icon-printer\" @click=\"handlePrint\">打印 / 另存为 PDF</el-button>\n      <el-button icon=\"el-icon-back\" @click=\"handleBack\">返回</el-button>\n    </div>\n\n    <!-- A4 纸面：屏幕预览 794px 等比模拟，打印时交给 @page 控版 -->\n    <div class=\"sheet\">\n      <div class=\"doc-title\">${comment}</div>\n      <div class=\"doc-meta\">\n        <span>单号：{{ master.id || \'—\' }}</span>\n        <span>打印时间：{{ printTime }}</span>\n      </div>\n\n<#if formColumns?size gt 0>\n      <!-- 主表信息区：两列键值网格，列取 isForm -->\n      <table class=\"kv-table\">\n<#list formColumns as c>\n<#if c_index % 2 == 0>\n        <tr>\n</#if>\n          <th class=\"kv-label\">${c.commentLabel}</th>\n          <td class=\"kv-value\"><#if c.hasEnum>{{ labelOf(\'${c.javaField}\', master.${c.javaField}) }}<#elseif c.isDatetime || c.isDate>{{ fmt(master.${c.javaField}) }}<#else>{{ master.${c.javaField} }}</#if></td>\n<#if c_index % 2 == 1>\n        </tr>\n<#elseif !c_has_next>\n          <td class=\"kv-value\"></td>\n        </tr>\n</#if>\n</#list>\n      </table>\n\n</#if>\n<#if hasChild>\n<#-- 明细块：每张子表一个，列取 isList（超 8 列截断），数值列自动合计 -->\n<#assign detailNo = 0 />\n<#list children as child>\n<#if child.listColumns?size gt 0>\n<#assign detailNo = detailNo + 1 />\n<#assign cCols = child.listColumns />\n<#if cCols?size gt 8><#assign cCols = cCols[0..7] /></#if>\n<#assign sumIdx = -1 />\n<#list cCols as c><#if sumIdx == -1 && (c.javaType == \"BigDecimal\" || c.javaType == \"Double\" || c.javaType == \"Integer\" || c.javaType == \"Long\")><#assign sumIdx = c_index /></#if></#list>\n      <div class=\"section-title\">明细${detailNo}：${child.comment}</div>\n      <table class=\"detail-table\">\n        <thead>\n          <tr>\n            <th class=\"idx\">#</th>\n<#list cCols as c>\n            <th>${c.commentLabel}</th>\n</#list>\n          </tr>\n        </thead>\n        <tbody>\n          <tr v-for=\"(row, i) in rowsOf(\'${child.varName}\')\" :key=\"i\">\n            <td class=\"idx\">{{ i + 1 }}</td>\n<#list cCols as c>\n            <td><#if c.hasEnum>{{ labelOf(\'${child.varName}.${c.javaField}\', row.${c.javaField}) }}<#elseif c.isDatetime || c.isDate>{{ fmt(row.${c.javaField}) }}<#else>{{ row.${c.javaField} }}</#if></td>\n</#list>\n          </tr>\n        </tbody>\n<#if sumIdx != -1>\n        <tfoot>\n          <tr class=\"sum-row\">\n            <td :colspan=\"${sumIdx + 1}\" class=\"sum-label\">合&nbsp;&nbsp;计</td>\n<#list cCols[sumIdx..] as c>\n<#if c.javaType == \"BigDecimal\" || c.javaType == \"Double\" || c.javaType == \"Integer\" || c.javaType == \"Long\">\n            <td class=\"sum-num\">{{ colSum(\'${child.varName}\', \'${c.javaField}\') }}</td>\n<#else>\n            <td></td>\n</#if>\n</#list>\n          </tr>\n        </tfoot>\n</#if>\n      </table>\n\n</#if>\n</#list>\n<#-- 孙表块：与子表块同版式平铺，行数据由前端从子表 rows 展平 -->\n<#list children as child>\n<#list child.grandChildren as gc>\n<#if gc.listColumns?size gt 0>\n<#assign detailNo = detailNo + 1 />\n<#assign gCols = gc.listColumns />\n<#if gCols?size gt 8><#assign gCols = gCols[0..7] /></#if>\n<#assign gSumIdx = -1 />\n<#list gCols as c><#if gSumIdx == -1 && (c.javaType == \"BigDecimal\" || c.javaType == \"Double\" || c.javaType == \"Integer\" || c.javaType == \"Long\")><#assign gSumIdx = c_index /></#if></#list>\n      <div class=\"section-title\">明细${detailNo}：${gc.comment}（${child.comment}下级）</div>\n      <table class=\"detail-table\">\n        <thead>\n          <tr>\n            <th class=\"idx\">#</th>\n<#list gCols as c>\n            <th>${c.commentLabel}</th>\n</#list>\n          </tr>\n        </thead>\n        <tbody>\n          <tr v-for=\"(row, i) in rowsOf(\'${child.varName}.${gc.varName}\')\" :key=\"i\">\n            <td class=\"idx\">{{ i + 1 }}</td>\n<#list gCols as c>\n            <td><#if c.hasEnum>{{ labelOf(\'${child.varName}.${gc.varName}.${c.javaField}\', row.${c.javaField}) }}<#elseif c.isDatetime || c.isDate>{{ fmt(row.${c.javaField}) }}<#else>{{ row.${c.javaField} }}</#if></td>\n</#list>\n          </tr>\n        </tbody>\n<#if gSumIdx != -1>\n        <tfoot>\n          <tr class=\"sum-row\">\n            <td :colspan=\"${gSumIdx + 1}\" class=\"sum-label\">合&nbsp;&nbsp;计</td>\n<#list gCols[gSumIdx..] as c>\n<#if c.javaType == \"BigDecimal\" || c.javaType == \"Double\" || c.javaType == \"Integer\" || c.javaType == \"Long\">\n            <td class=\"sum-num\">{{ colSum(\'${child.varName}.${gc.varName}\', \'${c.javaField}\') }}</td>\n<#else>\n            <td></td>\n</#if>\n</#list>\n          </tr>\n        </tfoot>\n</#if>\n      </table>\n\n</#if>\n</#list>\n</#list>\n</#if>\n      <div class=\"sign-bar\">\n        <span>制单人：____________</span>\n        <span>审&nbsp;&nbsp;核：____________</span>\n        <span>批&nbsp;&nbsp;准：____________</span>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script>\n<#if hasChild>\nimport { get${className}WithChildren } from \'@/api/${moduleName}\'\n<#else>\nimport { get${className}Detail } from \'@/api/${moduleName}\'\n</#if>\n\n// 注释枚举内联：打印页独立于后台导航壳，不依赖字典接口即可回显中文\nconst PRINT_ENUMS = {\n<#assign enumEntryCount = 0 />\n<#list enumColumns as c>\n  \'${c.javaField}\': ${c.enumJs}<#assign enumEntryCount = enumEntryCount + 1 />,\n</#list>\n<#list children as child>\n<#list child.listColumns as c>\n<#if c.hasEnum>\n  \'${child.varName}.${c.javaField}\': ${c.enumJs}<#assign enumEntryCount = enumEntryCount + 1 />,\n</#if>\n</#list>\n<#list child.grandChildren as gc>\n<#list gc.listColumns as c>\n<#if c.hasEnum>\n  \'${child.varName}.${gc.varName}.${c.javaField}\': ${c.enumJs}<#assign enumEntryCount = enumEntryCount + 1 />,\n</#if>\n</#list>\n</#list>\n</#list>\n}\n\n// 合计列配置：BigDecimal/Double 走「分」整数累加（规避 JS 浮点误差），整数类型直接累加\nconst SUM_FIELDS = {\n<#list children as child>\n<#list child.listColumns as c>\n<#if c.javaType == \"BigDecimal\" || c.javaType == \"Double\" || c.javaType == \"Integer\" || c.javaType == \"Long\">\n  \'${child.varName}.${c.javaField}\': \'<#if c.javaType == \"BigDecimal\" || c.javaType == \"Double\">cents<#else>plain</#if>\',\n</#if>\n</#list>\n<#list child.grandChildren as gc>\n<#list gc.listColumns as c>\n<#if c.javaType == \"BigDecimal\" || c.javaType == \"Double\" || c.javaType == \"Integer\" || c.javaType == \"Long\">\n  \'${child.varName}.${gc.varName}.${c.javaField}\': \'<#if c.javaType == \"BigDecimal\" || c.javaType == \"Double\">cents<#else>plain</#if>\',\n</#if>\n</#list>\n</#list>\n</#list>\n}\n\nexport default {\n  name: \'Print${className}\',\n  data() {\n    return {\n      loading: false,\n      master: {},\n      // [{key, comment, rows}]，与 /with-children 响应同构\n      groups: [],\n      printTime: \'\'\n    }\n  },\n  created() {\n    this.printTime = this.now()\n    this.fetchData()\n  },\n  methods: {\n    async fetchData() {\n      this.loading = true\n      try {\n        const id = this.$route.params.id\n<#if hasChild>\n        const res = await get${className}WithChildren(id)\n        const data = (res && res.data) || {}\n        this.master = data.master || {}\n        this.groups = data.children || []\n<#else>\n        const res = await get${className}Detail(id)\n        this.master = (res && res.data) || {}\n</#if>\n      } catch (e) {\n        /* 拦截器已提示 */\n      } finally {\n        this.loading = false\n      }\n    },\n    rowsOf(key) {\n      const dot = key.indexOf(\'.\')\n      if (dot === -1) {\n        const g = this.groups.find(item => item.key === key)\n        return (g && g.rows) || []\n      }\n      // 孙表：从父组每行 gVar + \'s\' 里展平\n      const parentKey = key.slice(0, dot)\n      const gcField = key.slice(dot + 1) + \'s\'\n      const g = this.groups.find(item => item.key === parentKey)\n      const out = []\n      ;((g && g.rows) || []).forEach(row => {\n        ;(row[gcField] || []).forEach(item => out.push(item))\n      })\n      return out\n    },\n    labelOf(key, value) {\n      if (value === null || value === undefined || value === \'\') return \'\'\n      const opts = PRINT_ENUMS[key] || []\n      const hit = opts.find(o => String(o.value) === String(value))\n      return hit ? hit.label : value\n    },\n    colSum(groupKey, field) {\n      const mode = SUM_FIELDS[groupKey + \'.\' + field] || \'plain\'\n      const rows = this.rowsOf(groupKey)\n      let sum = 0\n      rows.forEach(row => {\n        const v = Number(row[field])\n        if (!isNaN(v)) {\n          sum += mode === \'cents\' ? Math.round(v * 100) : v\n        }\n      })\n      return mode === \'cents\' ? (sum / 100).toFixed(2) : String(sum)\n    },\n    fmt(v) {\n      if (v === null || v === undefined || v === \'\') return \'\'\n      return String(v).replace(\'T\', \' \')\n    },\n    now() {\n      const d = new Date()\n      const p = n => String(n).padStart(2, \'0\')\n      return d.getFullYear() + \'-\' + p(d.getMonth() + 1) + \'-\' + p(d.getDate())\n        + \' \' + p(d.getHours()) + \':\' + p(d.getMinutes())\n    },\n    handlePrint() {\n      window.print()\n    },\n    handleBack() {\n      if (window.history.length > 1) {\n        window.history.back()\n      } else {\n        window.close()\n      }\n    }\n  }\n}\n</script>\n\n<style scoped>\n/* 屏幕预览：按 A4 宽度 794px 等比模拟 */\n.print-wrap {\n  min-height: 100vh;\n  background: #f0f2f5;\n  padding: 16px 0 32px;\n}\n\n.print-toolbar {\n  width: 794px;\n  margin: 0 auto 12px;\n  text-align: right;\n}\n\n.sheet {\n  width: 794px;\n  min-height: 1000px;\n  margin: 0 auto;\n  padding: 40px 34px;\n  background: #fff;\n  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.12);\n  box-sizing: border-box;\n  color: #1f2d3d;\n}\n\n.doc-title {\n  text-align: center;\n  font-size: 22px;\n  font-weight: 700;\n  letter-spacing: 4px;\n  margin-bottom: 10px;\n}\n\n.doc-meta {\n  display: flex;\n  justify-content: space-between;\n  font-size: 12px;\n  color: #5a5e66;\n  margin-bottom: 14px;\n}\n\n.section-title {\n  font-size: 14px;\n  font-weight: 700;\n  margin: 16px 0 6px;\n}\n\n.kv-table,\n.detail-table {\n  width: 100%;\n  border-collapse: collapse;\n  table-layout: fixed;\n}\n\n.kv-table th,\n.kv-table td,\n.detail-table th,\n.detail-table td {\n  border: 1px solid #333;\n  padding: 5px 6px;\n  font-size: 12px;\n  line-height: 1.5;\n  word-break: break-all;\n}\n\n.kv-table th {\n  width: 96px;\n  background: #f7f8fa;\n  font-weight: 600;\n  text-align: left;\n}\n\n.detail-table th {\n  background: #f7f8fa;\n  font-weight: 600;\n}\n\n.detail-table .idx {\n  width: 34px;\n  text-align: center;\n}\n\n/* 跨页行为：表头自动重复、行不拦腰截断 */\n.detail-table thead {\n  display: table-header-group;\n}\n\n.detail-table tr {\n  break-inside: avoid;\n}\n\n.sum-row td {\n  font-weight: 700;\n  background: #fbfbfc;\n}\n\n.sum-num {\n  text-align: right;\n}\n\n.sign-bar {\n  display: flex;\n  justify-content: space-between;\n  margin-top: 42px;\n  padding: 0 12px;\n  font-size: 13px;\n}\n\n/* 打印：隐藏一切非单据元素，版面交给 @page */\n@media print {\n  @page {\n    size: A4 portrait;\n    margin: 14mm 12mm;\n  }\n\n  .no-print {\n    display: none !important;\n  }\n\n  .print-wrap {\n    background: #fff;\n    padding: 0;\n  }\n\n  .sheet {\n    width: auto;\n    min-height: 0;\n    padding: 0;\n    box-shadow: none;\n  }\n}\n</style>\n','src/views/${moduleName}/print.vue',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:22',NULL,'2026-11-10 12:53:22'),(2120016942006824961,'flowApi','审批流前端接口','frontend','import request from \'@/utils/request\'\n\n// V6.1 审批流全局接口（前端统一走 body 风格 /flow 端点，与业务 controller 的路径风格互补）\nexport function flowSubmit(flowCode, bizId, comment) {\n  return request({ url: \'/flow/submit\', method: \'post\', data: { flowCode, bizId, comment } })\n}\n\nexport function flowApprove(flowCode, bizId, comment) {\n  return request({ url: \'/flow/approve\', method: \'post\', data: { flowCode, bizId, comment } })\n}\n\nexport function flowReject(flowCode, bizId, comment) {\n  return request({ url: \'/flow/reject\', method: \'post\', data: { flowCode, bizId, comment } })\n}\n\nexport function getFlowRecords(flowCode, bizId) {\n  return request({ url: \'/flow/records\', method: \'get\', params: { flowCode, bizId } })\n}\n\nexport function getFlowState(flowCode, bizId) {\n  return request({ url: \'/flow/state\', method: \'get\', params: { flowCode, bizId } })\n}\n\nexport function getFlowTodo() {\n  return request({ url: \'/flow/todo\', method: \'get\' })\n}\n\nexport function getFlowDone() {\n  return request({ url: \'/flow/done\', method: \'get\' })\n}\n\nexport function getFlowTaskDetail(taskId) {\n  return request({ url: `/flow/task/${taskId}`, method: \'get\' })\n}\n\n// ===== 以下为手写区：自定义请求写在这里，重新生成不会被覆盖 =====\n','src/api/flow.js',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:22',NULL,'2026-11-10 12:53:22'),(2120016942073933826,'flowTodo','待办中心页','frontend','<template>\n  <div class=\"flow-todo\">\n    <el-tabs v-model=\"activeTab\">\n      <el-tab-pane label=\"我的待办\" name=\"todo\">\n        <el-table :data=\"todoList\" v-loading=\"loading\" border size=\"small\">\n          <el-table-column prop=\"flowName\" label=\"流程\" width=\"180\" />\n          <el-table-column prop=\"nodeName\" label=\"当前节点\" width=\"140\" />\n          <el-table-column prop=\"bizTable\" label=\"业务表\" width=\"180\" />\n          <el-table-column prop=\"bizId\" label=\"单据ID\" width=\"180\" />\n          <el-table-column prop=\"createTime\" label=\"到达时间\" min-width=\"150\" />\n          <el-table-column label=\"操作\" width=\"160\" fixed=\"right\">\n            <template slot-scope=\"{ row }\">\n              <el-button type=\"primary\" size=\"mini\" @click=\"openApprove(row)\">审批</el-button>\n            </template>\n          </el-table-column>\n        </el-table>\n      </el-tab-pane>\n      <el-tab-pane label=\"我的已办\" name=\"done\">\n        <el-table :data=\"doneList\" v-loading=\"loading\" border size=\"small\">\n          <el-table-column prop=\"flowCode\" label=\"流程\" width=\"180\" />\n          <el-table-column prop=\"nodeName\" label=\"处理节点\" width=\"140\" />\n          <el-table-column prop=\"bizId\" label=\"单据ID\" width=\"180\" />\n          <el-table-column prop=\"operTime\" label=\"处理时间\" min-width=\"150\" />\n        </el-table>\n      </el-tab-pane>\n    </el-tabs>\n\n    <el-dialog title=\"审批\" :visible.sync=\"dialogVisible\" width=\"460px\">\n      <div v-if=\"current\" style=\"margin-bottom: 12px; color: #909399; font-size: 13px;\">\n        流程：{{ current.flowName || current.flowCode }}　节点：{{ current.nodeName }}　单据：{{ current.bizId }}\n      </div>\n      <el-input v-model=\"comment\" type=\"textarea\" :rows=\"3\" placeholder=\"审批意见（可选）\" />\n      <span slot=\"footer\">\n        <el-button size=\"small\" @click=\"dialogVisible = false\">取消</el-button>\n        <el-button size=\"small\" type=\"danger\" @click=\"doApprove(false)\">驳 回</el-button>\n        <el-button size=\"small\" type=\"primary\" @click=\"doApprove(true)\">通 过</el-button>\n      </span>\n    </el-dialog>\n  </div>\n</template>\n\n<script>\nimport {\n  getFlowTodo, getFlowDone, flowApprove, flowReject, getFlowRecords\n} from \'@/api/flow\'\n\nexport default {\n  name: \'FlowTodo\',\n  data() {\n    return {\n      activeTab: \'todo\',\n      loading: false,\n      todoList: [],\n      doneList: [],\n      dialogVisible: false,\n      current: null,\n      comment: \'\'\n    }\n  },\n  created() {\n    this.load()\n  },\n  methods: {\n    async load() {\n      this.loading = true\n      try {\n        const [todo, done] = await Promise.all([getFlowTodo(), getFlowDone()])\n        this.todoList = (todo && todo.data) || []\n        this.doneList = (done && done.data) || []\n      } finally {\n        this.loading = false\n      }\n    },\n    openApprove(row) {\n      this.current = row\n      this.comment = \'\'\n      this.dialogVisible = true\n    },\n    async doApprove(approved) {\n      const row = this.current\n      const flowCode = row.flowCode\n      const bizId = row.bizId\n      try {\n        if (approved) {\n          await flowApprove(flowCode, bizId, this.comment)\n          this.$message.success(\'已通过\')\n        } else {\n          await flowReject(flowCode, bizId, this.comment)\n          this.$message.success(\'已驳回\')\n        }\n        this.dialogVisible = false\n        this.load()\n      } catch (e) {\n        // request.js 统一弹出错误，这里不再重复提示\n      }\n    }\n  }\n}\n</script>\n\n<style scoped>\n.flow-todo { padding: 16px; }\n</style>\n','src/views/flow/todo.vue',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:22',NULL,'2026-11-10 12:53:22'),(2120016942141042689,'payApi','支付前端接口','frontend','import request from \'@/utils/request\'\n\n// V6.3 支付能力包全局接口（amount 单位：元，后端统一转分存储）\nexport function createPayOrder(data) {\n  return request({ url: \'/pay/order\', method: \'post\', data })\n}\n\nexport function getPayOrder(outTradeNo) {\n  return request({ url: \'/pay/order/\' + outTradeNo, method: \'get\' })\n}\n\nexport function closePayOrder(outTradeNo) {\n  return request({ url: \'/pay/close/\' + outTradeNo, method: \'post\' })\n}\n\n// mock 渠道专用：本地模拟支付成功（真渠道下后端返回 404）\nexport function mockPay(outTradeNo) {\n  return request({ url: \'/pay/mock/pay/\' + outTradeNo, method: \'post\' })\n}\n\nexport function payOrderPage(query) {\n  return request({ url: \'/pay/order/page\', method: \'post\', data: query })\n}\n\n// ===== 以下为手写区：自定义请求写在这里，重新生成不会被覆盖 =====\n','src/api/pay.js',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:22',NULL,'2026-11-10 12:53:22'),(2120016942275260418,'payCashier','收银台页','frontend','<template>\n  <div class=\"cashier\">\n    <el-card shadow=\"never\">\n      <div slot=\"header\" class=\"hd\">\n        <span>收银台</span>\n        <el-tag size=\"mini\" type=\"info\">{{ channelText }}</el-tag>\n      </div>\n\n      <el-form :model=\"form\" label-width=\"90px\" style=\"max-width:480px\">\n        <el-form-item label=\"订单标题\">\n          <el-input v-model=\"form.subject\" placeholder=\"如：培训缴费\" />\n        </el-form-item>\n        <el-form-item label=\"金额（元）\">\n          <el-input-number v-model=\"form.amountYuan\" :min=\"0.01\" :precision=\"2\" :step=\"1\" style=\"width:200px\" />\n          <span class=\"tip\">数据库按「分」存储，此处以元输入</span>\n        </el-form-item>\n        <el-form-item v-if=\"form.businessType\" label=\"关联业务\">\n          <el-tag size=\"small\">{{ form.businessType }} {{ \'#\' + form.businessId }}</el-tag>\n        </el-form-item>\n        <el-form-item>\n          <el-button type=\"primary\" :loading=\"creating\" @click=\"createOrder\">生成支付单</el-button>\n        </el-form-item>\n      </el-form>\n\n      <el-divider v-if=\"order\" />\n\n      <div v-if=\"order\" class=\"pay-area\">\n        <div class=\"line\">商户单号：<b>{{ order.outTradeNo }}</b>\n          <el-tag size=\"mini\" :type=\"statusTagType(order.payStatus)\">{{ statusText(order.payStatus) }}</el-tag>\n        </div>\n\n        <!-- mock 渠道：一键模拟支付（走与真渠道同构的状态流转链路） -->\n        <template v-if=\"channel === \'mock\' && order.payStatus === 0\">\n          <el-button type=\"success\" :loading=\"mocking\" @click=\"mockPayNow\">模拟支付（立即成功）</el-button>\n          <div class=\"tip\">mock 渠道用于本地演示与流水线自检；接入真实商户后改 yml pay.channel 即切真渠道，零代码改动</div>\n        </template>\n\n        <!-- wxpay：前端 qrcode 出码（code_url） -->\n        <template v-if=\"channel === \'wxpay\' && order.payStatus === 0\">\n          <img v-if=\"qrDataUrl\" :src=\"qrDataUrl\" class=\"qr\" alt=\"微信支付二维码\">\n          <div class=\"tip\">请使用微信扫码支付；本页每 2 秒自动查单，成功后自动跳转</div>\n        </template>\n\n        <!-- alipay：pageExecute 返回的表单落空文档提交跳转 -->\n        <template v-if=\"channel === \'alipay\' && order.payStatus === 0\">\n          <el-button type=\"primary\" @click=\"gotoAli\">跳转支付宝支付</el-button>\n          <div class=\"tip\">本页每 2 秒自动查单，成功后自动跳转</div>\n        </template>\n\n        <div v-if=\"order.payStatus === 1\" class=\"done\">\n          <i class=\"el-icon-success\" style=\"color:#67c23a;font-size:42px\" />\n          <div>支付成功{{ redirect ? \'，即将跳转…\' : \'\' }}</div>\n        </div>\n      </div>\n    </el-card>\n  </div>\n</template>\n\n<script>\nimport QRCode from \'qrcode\'\nimport { createPayOrder, getPayOrder, mockPay, getPayChannel } from \'@/api/pay\'\n\nexport default {\n  name: \'PayCashier\',\n  data() {\n    return {\n      channel: \'mock\',\n      form: { subject: \'\', amountYuan: null, businessType: \'\', businessId: \'\', redirect: \'\' },\n      order: null,\n      qrDataUrl: \'\',\n      creating: false,\n      mocking: false,\n      timer: null\n    }\n  },\n  computed: {\n    channelText() {\n      return { mock: \'模拟支付\', wxpay: \'微信支付（扫码）\', alipay: \'支付宝\' }[this.channel] || this.channel\n    }\n  },\n  async mounted() {\n    const q = this.$route.query || {}\n    this.form.subject = q.subject || \'\'\n    this.form.amountYuan = q.amount ? Number(q.amount) : null\n    this.form.businessType = q.businessType || \'\'\n    this.form.businessId = q.businessId || \'\'\n    this.form.redirect = q.redirect || \'\'\n    try { this.channel = (await getPayChannel()).channel || \'mock\' } catch (e) { this.channel = \'mock\' }\n  },\n  beforeDestroy() {\n    if (this.timer) clearInterval(this.timer)\n  },\n  methods: {\n    async createOrder() {\n      if (!this.form.subject || !this.form.amountYuan) {\n        this.$message.warning(\'请填写订单标题与金额\')\n        return\n      }\n      this.creating = true\n      try {\n        const data = (await createPayOrder({\n          subject: this.form.subject,\n          amount: this.form.amountYuan,\n          businessType: this.form.businessType || undefined,\n          businessId: this.form.businessId || undefined,\n          redirect: this.form.redirect || undefined\n        })).data\n        this.order = data\n        if (data.qrContent) {\n          this.qrDataUrl = await QRCode.toDataURL(data.qrContent, { width: 200 })\n        }\n        if (data.payStatus === 0) this.startPolling()\n      } finally {\n        this.creating = false\n      }\n    },\n    async mockPayNow() {\n      this.mocking = true\n      try {\n        await mockPay(this.order.outTradeNo)\n        await this.refreshOnce()\n      } finally {\n        this.mocking = false\n      }\n    },\n    gotoAli() {\n      if (this.order.payForm) {\n        // pageExecute 返回自动提交表单：落空文档即跳转支付宝\n        const w = window.open(\'\', \'_blank\')\n        w.document.write(this.order.payForm)\n        w.document.close()\n      } else if (this.order.payUrl) {\n        window.location.href = this.order.payUrl\n      }\n    },\n    startPolling() {\n      if (this.timer) clearInterval(this.timer)\n      this.timer = setInterval(() => this.refreshOnce(), 2000)\n    },\n    async refreshOnce() {\n      try {\n        const data = (await getPayOrder(this.order.outTradeNo)).data\n        this.order = Object.assign({}, this.order, data)\n        if (data.payStatus === 1) {\n          if (this.timer) clearInterval(this.timer)\n          this.$message.success(\'支付成功\')\n          if (this.form.redirect) setTimeout(() => { this.$router.push(this.form.redirect) }, 1500)\n        }\n      } catch (e) { /* 查单失败静默，下一轮重试 */ }\n    },\n    statusText(s) { return { 0: \'待支付\', 1: \'成功\', 2: \'已关闭\', 3: \'已退款\' }[s] || s },\n    statusTagType(s) { return { 0: \'warning\', 1: \'success\', 2: \'info\', 3: \'danger\' }[s] || \'info\' }\n  }\n}\n</script>\n\n<style scoped>\n.cashier { padding: 16px; }\n.hd { display: flex; align-items: center; gap: 8px; }\n.tip { color: #909399; font-size: 12px; margin-top: 8px; }\n.line { margin-bottom: 12px; }\n.qr { width: 200px; height: 200px; border: 1px solid #ebeef5; border-radius: 4px; }\n.done { text-align: center; padding: 20px 0; }\n</style>\n','src/views/pay/cashier.vue',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:22',NULL,'2026-11-10 12:53:22'),(2120016942371729409,'payOrderPage','支付记录页','frontend','<template>\n  <div class=\"app-container\">\n    <el-card shadow=\"never\">\n      <!-- 查询区 -->\n      <el-form :inline=\"true\" :model=\"query\" size=\"small\" @submit.native.prevent>\n        <el-form-item label=\"商户单号\">\n          <el-input v-model=\"query.outTradeNo\" placeholder=\"精确匹配\" clearable style=\"width:200px\" />\n        </el-form-item>\n        <el-form-item label=\"状态\">\n          <el-select v-model=\"query.payStatus\" placeholder=\"全部\" clearable style=\"width:120px\">\n            <el-option label=\"待支付\" :value=\"0\" />\n            <el-option label=\"成功\" :value=\"1\" />\n            <el-option label=\"已关闭\" :value=\"2\" />\n            <el-option label=\"已退款\" :value=\"3\" />\n          </el-select>\n        </el-form-item>\n        <el-form-item>\n          <el-button type=\"primary\" icon=\"el-icon-search\" @click=\"load(1)\">查询</el-button>\n          <el-button icon=\"el-icon-refresh\" @click=\"reset\">重置</el-button>\n        </el-form-item>\n      </el-form>\n\n      <!-- 列表 -->\n      <el-table v-loading=\"loading\" :data=\"rows\" border size=\"small\">\n        <el-table-column prop=\"outTradeNo\" label=\"商户单号\" width=\"220\" show-overflow-tooltip />\n        <el-table-column prop=\"subject\" label=\"标题\" min-width=\"160\" show-overflow-tooltip />\n        <el-table-column label=\"金额（元）\" width=\"110\" align=\"right\">\n          <template slot-scope=\"{ row }\">{{ fenToYuan(row.amount) }}</template>\n        </el-table-column>\n        <el-table-column prop=\"payChannel\" label=\"渠道\" width=\"90\" />\n        <el-table-column label=\"状态\" width=\"90\" align=\"center\">\n          <template slot-scope=\"{ row }\">\n            <el-tag size=\"mini\" :type=\"statusTagType(row.payStatus)\">{{ statusText(row.payStatus) }}</el-tag>\n          </template>\n        </el-table-column>\n        <el-table-column label=\"业务\" width=\"160\" show-overflow-tooltip>\n          <template slot-scope=\"{ row }\">{{ row.businessType ? row.businessType + \' #\' + row.businessId : \'—\' }}</template>\n        </el-table-column>\n        <el-table-column prop=\"paidAt\" label=\"支付时间\" width=\"160\" />\n        <el-table-column label=\"操作\" width=\"200\" fixed=\"right\">\n          <template slot-scope=\"{ row }\">\n            <el-button type=\"text\" size=\"mini\" @click=\"doQuery(row)\">查单</el-button>\n            <el-button v-if=\"row.payStatus === 0\" type=\"text\" size=\"mini\" class=\"danger-link\" @click=\"doClose(row)\">关单</el-button>\n            <el-button v-if=\"row.payStatus === 0\" type=\"text\" size=\"mini\" @click=\"goPay(row)\">去支付</el-button>\n          </template>\n        </el-table-column>\n      </el-table>\n\n      <el-pagination\n        style=\"margin-top:12px;text-align:right\"\n        background\n        layout=\"total, prev, pager, next, sizes\"\n        :total=\"total\"\n        :current-page.sync=\"query.pageNum\"\n        :page-size.sync=\"query.pageSize\"\n        :page-sizes=\"[10, 20, 50]\"\n        @current-change=\"load()\"\n        @size-change=\"load(1)\"\n      />\n    </el-card>\n  </div>\n</template>\n\n<script>\nimport { payOrderPage, getPayOrder, closePayOrder } from \'@/api/pay\'\n\nexport default {\n  name: \'PayOrderPage\',\n  data() {\n    return {\n      query: { pageNum: 1, pageSize: 10, outTradeNo: \'\', payStatus: undefined },\n      rows: [],\n      total: 0,\n      loading: false\n    }\n  },\n  mounted() { this.load(1) },\n  methods: {\n    async load(page) {\n      if (page) this.query.pageNum = page\n      this.loading = true\n      try {\n        const data = (await payOrderPage(this.query)).data\n        this.rows = data.records || []\n        this.total = Number(data.total || 0)\n      } finally {\n        this.loading = false\n      }\n    },\n    reset() {\n      this.query.outTradeNo = \'\'\n      this.query.payStatus = undefined\n      this.load(1)\n    },\n    async doQuery(row) {\n      const data = (await getPayOrder(row.outTradeNo)).data\n      Object.assign(row, data)\n      this.$message.success(\'已同步渠道最新状态：\' + this.statusText(data.payStatus))\n    },\n    doClose(row) {\n      this.$confirm(\'关闭后该支付单不可再支付，确认？\', \'关单\', { type: \'warning\' })\n        .then(async() => {\n          await closePayOrder(row.outTradeNo)\n          this.$message.success(\'已关闭\')\n          this.load()\n        }).catch(() => {})\n    },\n    goPay(row) {\n      this.$router.push({ path: \'/pay/cashier\', query: {\n        subject: row.subject, amount: this.fenToYuan(row.amount), redirect: \'/pay/order\'\n      } })\n    },\n    fenToYuan(fen) { return (Number(fen || 0) / 100).toFixed(2) },\n    statusText(s) { return { 0: \'待支付\', 1: \'成功\', 2: \'已关闭\', 3: \'已退款\' }[s] || s },\n    statusTagType(s) { return { 0: \'warning\', 1: \'success\', 2: \'info\', 3: \'danger\' }[s] || \'info\' }\n  }\n}\n</script>\n\n<style scoped>\n.danger-link { color: #f56c6c; }\n</style>\n','src/views/pay/order.vue',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:22',NULL,'2026-11-10 12:53:22'),(2120016942434643970,'routerSnippet','路由片段','shared','{\n  path: \'${moduleName}\',\n  name: \'${className}\',\n  component: () => import(\'@/views/${moduleName}/index.vue\'),\n  meta: { title: \'${comment}\' }\n},\n<#if genPrint>\n{\n  // V4.5 打印单据：无 layout 顶层路由，打印页必须脱离后台导航壳，否则打出来带侧边栏\n  path: \'/print/${moduleName}/:id\',\n  name: \'Print${className}\',\n  component: () => import(\'@/views/${moduleName}/print.vue\'),\n  meta: { title: \'${comment}打印\' }\n},\n</#if>\n','router-snippet.txt',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:22',NULL,'2026-11-10 12:53:22'),(2120016942573056002,'readme','使用说明','shared','代码生成器产物使用说明\n======================\n\n1. 后端文件：按包内相对路径合并到对应 shop-service-* 模块的\n   src/main/java/<package>/ 目录下（entity/mapper/service/dto/vo/controller）。\n2. 前端文件：src/api/*.js 与 src/views/*/index.vue 直接放入\n   CrossShopFrontPage 对应目录。\n3. 路由注册：打开 router-snippet.txt，把片段追加到\n   src/router/index.js 对应菜单的 children 中（手动合并）。\n4. 后端如使用新模块，确认该模块已配置 MybatisPlusConfig\n   （PaginationInnerInterceptor），否则分页 total 恒为 0。\n5. 打印单据：<#if (genPrint)!false>本次产物含 src/views/*/print.vue（A4 打印页，\n   路由为无 layout 顶层路由 /print/<模块>/:id，已在 router-snippet.txt 里），\n   列表操作列有「打印」按钮，浏览器打印或另存为 PDF 均可。\n   <#else>本次产物不含打印页（表配置 gen_print 未开启）。</#if>\n6. 明细打印列超过 8 列时自动精简到前 8 列；如需全部列打印，\n   在表配置里把非关键列的「列表显示」关掉后重新生成。\n','README-使用说明.txt',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:22',NULL,'2026-11-10 12:53:22'),(2120016942627581953,'crudControllerTest','集成测试（CRUD）','test','package ${pkg};\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.http.MediaType;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.test.web.servlet.request.MockMvcRequestBuilders;\n\nimport static org.hamcrest.Matchers.nullValue;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\n/**\n * ${comment} CRUD 集成测试（代码生成器 V6.7 自动生成，重新生成会覆盖本文件）。\n *\n * <p>H2 内存库 + 真实鉴权链（基类直插 sys_session 造登录态），只覆盖 generated 端点：\n * page → add → detail → update → delete → 未登录 401。业务规则断言请另建测试类。\n */\nclass ${className}ControllerTest extends LoginStateTestSupport {\n\n    @Autowired\n    private JdbcTemplate jdbcTemplate;\n\n    /** 新增一条最小合法记录，返回自增 id（add 接口不回 id，从库里取最后一条） */\n    private Long addRow() throws Exception {\n        mockMvc.perform(MockMvcRequestBuilders.post(\"/${moduleName}<#if hasChild>/save-with-children</#if>\")\n                        .header(\"Authorization\", bearer())\n                        .contentType(MediaType.APPLICATION_JSON)\n                        .content(saveBody()))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.code\").value(200));\n        return jdbcTemplate.queryForObject(\"SELECT MAX(id) FROM ${tableName}\", Long.class);\n    }\n\n    /** 业务字段 JSON（平台按列模型生成；唯一列值运行时随机，避免测试互撞唯一键） */\n    private String fieldsJson() {\n        return ${testFieldsJsonExpr};\n    }\n\n    private String saveBody() {\n        return fieldsJson();\n    }\n\n    /** 修改体 = id + 同一业务字段集（{@code {\"id\":1,...}}：fieldsJson 去掉左花括号接 id） */\n    private String updateBody(long id) {\n        return \"{\\\"id\\\":\" + id + \",\" + fieldsJson().substring(1);\n    }\n\n    private String suffix() {\n        return \"it\" + System.nanoTime();\n    }\n\n    @Test\n    void pageReturnsRecords() throws Exception {\n        addRow();\n        mockMvc.perform(MockMvcRequestBuilders.post(\"/${moduleName}/page\")\n                        .header(\"Authorization\", bearer())\n                        .contentType(MediaType.APPLICATION_JSON)\n                        .content(\"{\\\"pageNum\\\":1,\\\"pageSize\\\":10}\"))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.code\").value(200))\n                .andExpect(jsonPath(\"$.data.records\").isArray());\n    }\n\n    <#if ctrlDetailApi>\n    @Test\n    void addThenDetailReturnsSameId() throws Exception {\n        Long id = addRow();\n        // VO 的 Long id 走 LongIdJacksonConfig 序列化为字符串（JS 精度保护，坑 57 同源）\n        mockMvc.perform(MockMvcRequestBuilders.get(\"/${moduleName}/\" + id)\n                        .header(\"Authorization\", bearer()))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.code\").value(200))\n                .andExpect(jsonPath(\"$.data.id\").value(String.valueOf(id)));\n    }\n    </#if>\n\n    <#if ctrlEditApi || hasChild>\n    @Test\n    void updateReturnsOk() throws Exception {\n        Long id = addRow();\n        mockMvc.perform(MockMvcRequestBuilders.<#if hasChild>post(\"/${moduleName}/save-with-children\")<#else>put(\"/${moduleName}\")</#if>\n                        .header(\"Authorization\", bearer())\n                        .contentType(MediaType.APPLICATION_JSON)\n                        .content(updateBody(id)))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.code\").value(200));\n    }\n    </#if>\n\n    <#if ctrlDeleteApi>\n    @Test\n    void deleteThenDetailIsEmpty() throws Exception {\n        Long id = addRow();\n        mockMvc.perform(MockMvcRequestBuilders.delete(\"/${moduleName}/\" + id)\n                        .header(\"Authorization\", bearer()))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.code\").value(200));\n        // 逻辑删后详情返回 200 + data=null（Result.ok(null)），而非 404\n        mockMvc.perform(MockMvcRequestBuilders.get(\"/${moduleName}/\" + id)\n                        .header(\"Authorization\", bearer()))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.code\").value(200))\n                .andExpect(jsonPath(\"$.data\").value(nullValue()));\n    }\n    </#if>\n\n    @Test\n    void anonymousRequestIsRejected() throws Exception {\n        // AuthContextFilter 未命中 token 时直接 SC_UNAUTHORIZED（HTTP 401，非 200+code）\n        mockMvc.perform(MockMvcRequestBuilders.post(\"/${moduleName}/page\")\n                        .contentType(MediaType.APPLICATION_JSON)\n                        .content(\"{\\\"pageNum\\\":1,\\\"pageSize\\\":10}\"))\n                .andExpect(status().isUnauthorized());\n    }\n}\n','${testJavaBase}/${className}ControllerTest.java',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:22',NULL,'2026-11-10 12:53:22'),(2120016942694690818,'testSchemaTable','测试库建表（H2）','test','-- ${comment} 测试库建表（H2 MODE=MySQL；由代码生成器 V6.7 逐表落盘，重新生成覆盖）\n-- 与正式 db/*.sql 同一列模型产出；转换规则：去 ENGINE/CHARSET/表注释/ON UPDATE\nCREATE TABLE IF NOT EXISTS ${tableName} (\n  id bigint NOT NULL AUTO_INCREMENT COMMENT \'主键\',\n<#list bizCols as c>\n  ${c.dbField} ${c.columnType}<#if c.isRequired> NOT NULL</#if> DEFAULT NULL COMMENT \'${c.columnComment}\',\n</#list>  deleted tinyint NOT NULL DEFAULT 0 COMMENT \'逻辑删除\',\n  create_by bigint NULL COMMENT \'创建人\',\n  create_time datetime NULL COMMENT \'创建时间\',\n  update_by bigint NULL COMMENT \'更新人\',\n  update_time datetime NULL COMMENT \'更新时间\',\n  PRIMARY KEY (id)\n);\n','${testResBase}/schema/table-${tableName}.sql',0,1,1,'全局种子模板',0,NULL,'2026-11-10 12:53:22',NULL,'2026-11-10 12:53:22');
