INSERT INTO `sys_flow_def` VALUES (1,'v61_leave_flow','请假审批流','v61_leave','status','[{\"from\":\"0\",\"to\":\"1\",\"roleCode\":\"manager\"},{\"from\":\"1\",\"to\":\"2\",\"roleCode\":\"hr\",\"rejectTo\":\"0\"}]','<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<definitions xmlns=\"http://www.omg.org/spec/BPMN/20100524/MODEL\"\n            xmlns:activiti=\"http://activiti.org/bpmn\"\n            targetNamespace=\"http://codegen.local/flows\">\n  <process id=\"v61_leave_flow\" name=\"请假审批流\" isExecutable=\"true\">\n    <startEvent id=\"start\" name=\"提交\"/>\n    <sequenceFlow id=\"flow_in_s1\" sourceRef=\"start\" targetRef=\"task_s1\"/>\n    <userTask id=\"task_s1\" name=\"1\" activiti:candidateGroups=\"manager\"/>\n    <exclusiveGateway id=\"gw_s1\" name=\"1判定\"/>\n    <sequenceFlow id=\"flow_task_gw_s1\" sourceRef=\"task_s1\" targetRef=\"gw_s1\"/>\n    <sequenceFlow id=\"flow_in_s2\" sourceRef=\"gw_s1\" targetRef=\"task_s2\"/>\n    <userTask id=\"task_s2\" name=\"2\" activiti:candidateGroups=\"hr\"/>\n    <exclusiveGateway id=\"gw_s2\" name=\"2判定\"/>\n    <sequenceFlow id=\"flow_task_gw_s2\" sourceRef=\"task_s2\" targetRef=\"gw_s2\"/>\n    <endEvent id=\"end\" name=\"结束\"/>\n    <sequenceFlow id=\"flow_ap_s1\" name=\"通过\" sourceRef=\"gw_s1\" targetRef=\"task_s2\">\n      <conditionExpression xsi:type=\"tFormalExpression\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\">${approved == true}</conditionExpression>\n    </sequenceFlow>\n    <sequenceFlow id=\"flow_ap_s2\" name=\"通过\" sourceRef=\"gw_s2\" targetRef=\"end\">\n      <conditionExpression xsi:type=\"tFormalExpression\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\">${approved == true}</conditionExpression>\n    </sequenceFlow>\n    <sequenceFlow id=\"flow_rj_s1\" name=\"驳回\" sourceRef=\"gw_s1\" targetRef=\"start\">\n      <conditionExpression xsi:type=\"tFormalExpression\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\">${approved == false}</conditionExpression>\n    </sequenceFlow>\n    <sequenceFlow id=\"flow_rj_s2\" name=\"驳回\" sourceRef=\"gw_s2\" targetRef=\"start\">\n      <conditionExpression xsi:type=\"tFormalExpression\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\">${approved == false}</conditionExpression>\n    </sequenceFlow>\n  </process>\n</definitions>\n',1,NULL,'2026-10-25 20:12:05','2026-10-25 20:12:09',NULL,NULL,0);
